void checkAndClosePurchaseOrder(int purchase_order_id)
{
                 	po_rec = Purchase_Order[ID == purchase_order_id];
                 	if(po_rec.ID == null)
                 	{
                 		return;
                 	}
                 	po_lines = Purchase_Order_Details[Purchase_Order == purchase_order_id];
                 	if(po_lines.count() == 0)
                 	{
                 		return;
                 	}
                 	all_received = true;
                 	all_used = true;
                 	for each  line in po_lines
                 	{
                 		qty_ordered = ifnull(line.Quantity_Ordered,0.0);
                 		qty_received = ifnull(line.Quantity_Received,0.0);
                 		stock_condition = ifnull(line.Stock_Condition,"").trim();
                 		if(qty_received < qty_ordered)
                 		{
                 			all_received = false;
                 			break;
                 		}
                 		if(stock_condition != "Used")
                 		{
                 			all_used = false;
                 			break;
                 		}
                 	}
                 	if(all_received == true && all_used == true)
                 	{
                 		po_rec.PO_Status="Closed";
                 		po_rec.Payment_Status="Not Payable";
                 	}
                 	else
                 	{
                 		po_rec.PO_Status="Open";
                 		po_rec.Payment_Status="Not Paid";
                 	}
                 }

map deletePurchaseOrderFromCleanSand(string source_record_id, string source_form)
{
                 	resp = Map();
                 	resp.put("ok",false);
                 	if(source_record_id == null || source_record_id.trim() == "")
                 	{
                 		resp.put("message","Source Record ID is required.");
                 		return resp;
                 	}
                 	source_id_num = source_record_id.toLong();
                 	store_po = Purchase_Order[Source_Record_ID == source_id_num && Source_Form == source_form];
                 	if(store_po.ID == null)
                 	{
                 		resp.put("ok",true);
                 		resp.put("message","No Store PO found to delete.");
                 		return resp;
                 	}
                 	store_details = Purchase_Order_Details[Purchase_Order == store_po.ID];
                 	for each  det in store_details
                 	{
                 		delete from Purchase_Order_Details[ID == det.ID];
                 	}
                 	delete from Purchase_Order[ID == store_po.ID];
                 	resp.put("ok",true);
                 	resp.put("message","Store PO and PO Details deleted from Clean Sand Management.");
                 	return resp;
                 }

