map delete_item_issuing_from_CleanSand(int freedom_source_id)
{
                 	resp = Map();
                 	resp.put("ok",false);
                 	resp.put("message","Started");
                 	if(freedom_source_id == null)
                 	{
                 		resp.put("message","CleanSand source ID is null.");
                 		return resp;
                 	}
                 	affected_items = List();
                 	txns = Stock_Transactions[Source_Form == "Clean Sand Management - Item Issuing Details" && Source_Record_ID == freedom_source_id];
                 	for each  t in txns
                 	{
                 		tx_item = t.Item;
                 		tx_store = t.Store;
                 		tx_qty = ifnull(t.Quantity,0.0);
                 		tx_cond = ifnull(t.Stock_Condition,"New").trim();
                 		if(tx_cond == "")
                 		{
                 			tx_cond = "New";
                 		}
                 		if(tx_item != null && affected_items.contains(tx_item) == false)
                 		{
                 			affected_items.add(tx_item);
                 		}
                 		if(tx_item != null && tx_store != null && tx_qty > 0)
                 		{
                 			if(t.Transaction_Type == "Stock Out")
                 			{
                 				thisapp.stock.adjust_item_stock(tx_item,tx_qty,tx_cond);
                 				thisapp.stock.apply_ledger_delta(tx_item,tx_store,tx_qty,tx_cond);
                 			}
                 			else if(t.Transaction_Type == "Stock In")
                 			{
                 				reverse_qty = 0.0 - tx_qty;
                 				thisapp.stock.adjust_item_stock(tx_item,reverse_qty,tx_cond);
                 				thisapp.stock.apply_ledger_delta(tx_item,tx_store,reverse_qty,tx_cond);
                 			}
                 			thisapp.stock.rebuild_store_item_stock_costs(tx_item,tx_store,tx_cond);
                 		}
                 		delete from Stock_Transactions[ID == t.ID];
                 	}
                 	for each  item_id in affected_items
                 	{
                 		if(item_id != null)
                 		{
                 			thisapp.stock.rebuild_item_balances(item_id);
                 		}
                 	}
                 	resp.put("ok",true);
                 	resp.put("message","Clean Sand Management item issuing transactions reversed.");
                 	return resp;
                 }

