map getStoreItemStock(map Map_input)
{
                 	response = Map();
                 	itemID = Map_input.get("Item_ID");
                 	stockRec = Store_Item_Stock[Item == itemID && Display_Name_Store.contains("Concrete Products")];
                 	if(stockRec.ID != null)
                 	{
                 		uomConv = Unit_Of_Measure_Conversion[Item == itemID && Base_Unit_Of_Measure == stockRec.Item.Base_Unit_Of_Measure];
                 		response.put("Success",true);
                 		response.put("Store_Item_Stock",stockRec.ID);
                 		response.put("Store",stockRec.Store);
                 		response.put("Display_Name_Store",stockRec.Display_Name_Store);
                 		response.put("Quantity_Available",ifnull(stockRec.Qty_On_Hand,0.0));
                 		if(uomConv.ID != null)
                 		{
                 			response.put("Unit_Of_Measure",uomConv.ID);
                 			response.put("Display_Name_Unit_Of_Measure",uomConv.Display_Name_Base_Unit_Of_Measure);
                 		}
                 		else
                 		{
                 			response.put("Unit_Of_Measure",null);
                 			response.put("Display_Name_Unit_Of_Measure","");
                 		}
                 	}
                 	else
                 	{
                 		response.put("Success",false);
                 		response.put("Message","No Concrete Products stock found for selected item.");
                 	}
                 	return response;
                 }

map get_next_document_number(string doc_type, int company_id, string po_type)
{
                 	result = Map();
                 	result.put("ok",false);
                 	result.put("message","");
                 	result.put("po_number",null);
                 	if(doc_type == null || doc_type.trim() == "")
                 	{
                 		result.put("message","Document Type is missing.");
                 		return result;
                 	}
                 	// ==========================
                 	// INTERNAL TRANSFER
                 	// ==========================
                 	if(po_type == "Internal Transfer")
                 	{
                 		series = Document_Series[Document_Type == doc_type && Prefix == "IT" && Status == "Active"];
                 		if(series.ID == null)
                 		{
                 			result.put("message","No ACTIVE IT Document Series found.");
                 			return result;
                 		}
                 		next_no = ifnull(series.Next_Number,1);
                 		no_str = next_no.toString();
                 		if(no_str.length() == 1)
                 		{
                 			no_str = "0000" + no_str;
                 		}
                 		else if(no_str.length() == 2)
                 		{
                 			no_str = "000" + no_str;
                 		}
                 		else if(no_str.length() == 3)
                 		{
                 			no_str = "00" + no_str;
                 		}
                 		else if(no_str.length() == 4)
                 		{
                 			no_str = "0" + no_str;
                 		}
                 		final_no = series.Prefix + "-" + no_str;
                 		series.Next_Number=next_no + 1;
                 		result.put("ok",true);
                 		result.put("po_number",final_no);
                 		return result;
                 	}
                 	// ==========================
                 	// EXTERNAL PURCHASE (existing logic)
                 	// ==========================
                 	if(company_id == null)
                 	{
                 		result.put("message","Company is missing.");
                 		return result;
                 	}
                 	series = Document_Series[Document_Type == doc_type && Company == company_id && Status == "Active"];
                 	if(series.ID == null)
                 	{
                 		result.put("message","No ACTIVE Document Series found for this Company.");
                 		return result;
                 	}
                 	prefix = ifnull(series.Prefix,"").trim();
                 	company_pad = ifnull(series.Company_Pad,0).toString();
                 	next_no = ifnull(series.Next_Number,1);
                 	// ---- Pad Company (3 digits) ----
                 	if(company_pad.length() == 1)
                 	{
                 		company_pad = "00" + company_pad;
                 	}
                 	else if(company_pad.length() == 2)
                 	{
                 		company_pad = "0" + company_pad;
                 	}
                 	// ---- Pad Next Number (5 digits) ----
                 	no_str = next_no.toString();
                 	if(no_str.length() == 1)
                 	{
                 		no_str = "0000" + no_str;
                 	}
                 	else if(no_str.length() == 2)
                 	{
                 		no_str = "000" + no_str;
                 	}
                 	else if(no_str.length() == 3)
                 	{
                 		no_str = "00" + no_str;
                 	}
                 	else if(no_str.length() == 4)
                 	{
                 		no_str = "0" + no_str;
                 	}
                 	final_no = prefix + company_pad + "-" + no_str;
                 	series.Next_Number=next_no + 1;
                 	result.put("ok",true);
                 	result.put("po_number",final_no);
                 	return result;
                 }

map recheckPurchaseOrdersFromBill(string bill_no)
{
                 	resp = Map();
                 	resp.put("ok",false);
                 	if(bill_no == null || bill_no.trim() == "")
                 	{
                 		resp.put("msg","Bill number is empty.");
                 		return resp;
                 	}
                 	bill_rec = Bill[Bill_Number == bill_no];
                 	if(bill_rec.ID == null)
                 	{
                 		resp.put("msg","Store bill not found: " + bill_no);
                 		return resp;
