map updateBillFromPayment(map payload)
{
                 	resp = Map();
                 	resp.put("ok",false);
                 	resp.put("msg","");
                 	resp.put("bill_amount_paid",0.0);
                 	resp.put("bill_balance_due",0.0);
                 	resp.put("bill_status","");
                 	resp.put("payment_status","");
                 	resp.put("group_allocations",List());
                 	bill_no = ifnull(payload.get("Bill_Number"),"").trim();
                 	total_paid_in = round(ifnull(payload.get("Total_Paid"),0.0),2);
                 	payment_date = payload.get("Payment_Date");
                 	if(payment_date == null)
                 	{
                 		payment_date = zoho.currentdate;
                 	}
                 	if(bill_no == "")
                 	{
                 		resp.put("msg","Bill_Number is required.");
                 		return resp;
                 	}
                 	bill_rec = Bill[Bill_Number == bill_no];
                 	if(bill_rec.ID == null)
                 	{
                 		resp.put("msg","Store Bill not found for Bill Number: " + bill_no);
                 		return resp;
                 	}
                 	details_total = 0.0;
                 	bill_rows = Bill_Details[Bill == bill_rec.ID];
                 	for each  br in bill_rows
                 	{
                 		details_total = round(details_total + ifnull(br.Line_Total,0.0),2);
                 	}
                 	services_total = 0.0;
                 	service_rows = Service_Details[Bill == bill_rec.ID];
                 	for each  sr in service_rows
                 	{
                 		services_total = round(services_total + ifnull(sr.Line_Total,0.0),2);
                 	}
                 	grand_total = round(details_total + services_total,2);
                 	tax_amt = round(ifnull(bill_rec.Tax_Amount,0.0),2);
                 	disc_amt = round(ifnull(bill_rec.Discount_Amount,0.0),2);
                 	amount_due = round(grand_total + tax_amt - disc_amt,2);
                 	if(amount_due < 0)
                 	{
                 		amount_due = 0.0;
                 	}
                 	amount_paid = round(total_paid_in,2);
                 	if(amount_paid < 0)
                 	{
                 		amount_paid = 0.0;
                 	}
                 	if(amount_paid > amount_due)
                 	{
                 		amount_paid = amount_due;
                 	}
                 	balance_due = round(amount_due - amount_paid,2);
                 	if(balance_due < 0)
                 	{
                 		balance_due = 0.0;
                 	}
                 	new_bill_status = if(grand_total > 0,"Billed","Draft");
                 	if(ifnull(bill_rec.Bill_Status,"") == "Cancelled")
                 	{
                 		new_bill_status = "Cancelled";
                 	}
                 	new_payment_status = "Not Paid";
                 	if(amount_paid <= 0)
                 	{
                 		new_payment_status = "Not Paid";
                 	}
                 	else if(balance_due > 0)
                 	{
                 		new_payment_status = "Partially Paid";
                 	}
                 	else
                 	{
                 		new_payment_status = "Paid";
                 	}
                 	bill_rec.Services_Total=services_total;
                 	bill_rec.Total_Amount=grand_total;
                 	bill_rec.Amount_Due=amount_due;
                 	bill_rec.Amount_Paid=amount_paid;
                 	bill_rec.Balance_Due=balance_due;
                 	bill_rec.Bill_Status=new_bill_status;
                 	bill_rec.Payment_Status=new_payment_status;
                 	// ======================================
                 	// UPDATE PURCHASE ORDER PAYMENT STATUS
                 	// ======================================
                 	po_map = Map();
                 	bill_detail_rows = Bill_Details[Bill == bill_rec.ID];
                 	for each  bd in bill_detail_rows
                 	{
                 		if(bd.Item != null)
                 		{
                 			po_det = Purchase_Order_Details[ID == bd.Item];
                 			if(po_det.ID != null && po_det.Purchase_Order != null)
                 			{
                 				po_key = po_det.Purchase_Order.ID.toString();
                 				po_map.put(po_key,po_det.Purchase_Order.ID);
                 			}
                 		}
                 	}
                 	for each  po_key in po_map.keys()
                 	{
                 		po_rec = Purchase_Order[ID == po_map.get(po_key)];
                 		if(po_rec.ID != null)
                 		{
                 			po_total_paid = 0.0;
                 			paid_bill_map = Map();
                 			related_bill_details = Bill_Details[Item.Purchase_Order == po_rec.ID];
                 			for each  rbd in related_bill_details
                 			{
                 				if(rbd.Bill != null)
                 				{
                 					related_bill = Bill[ID == rbd.Bill];
                 					if(related_bill.ID != null)
                 					{
                 						paid_bill_key = related_bill.ID.toString();
                 						if(paid_bill_map.get(paid_bill_key) == null)
                 						{
                 							paid_bill_map.put(paid_bill_key,related_bill.ID);
                 							po_total_paid = round(po_total_paid + ifnull(related_bill.Amount_Paid,0.0),2);
                 						}
                 					}
                 				}
                 			}
                 			po_rec.PO_Total_Paid=po_total_paid;
                 			po_total = round(ifnull(po_rec.PO_Total,0.0),2);
                 			if(po_total_paid <= 0)
                 			{
                 				po_rec.Payment_Status="Not Paid";
                 			}
                 			else if(po_total_paid < po_total)
                 			{
                 				po_rec.Payment_Status="Partially Paid";
                 			}
                 			else
                 			{
                 				po_rec.Payment_Status="Paid";
                 			}
                 		}
                 	}
                 	group_alloc_list = List();
                 	resp.put("ok",true);
                 	resp.put("msg","Store Bill updated successfully.");
                 	resp.put("bill_number",bill_no);
                 	resp.put("bill_amount_due",amount_due);
                 	resp.put("bill_amount_paid",amount_paid);
                 	resp.put("bill_balance_due",balance_due);
                 	resp.put("bill_status",new_bill_status);
                 	resp.put("payment_status",new_payment_status);
                 	resp.put("services_total",services_total);
                 	resp.put("total_amount",grand_total);
                 	resp.put("group_allocations",group_alloc_list);
                 	return resp;
                 }

