string generator.Generate_SKU(int category_id)
{
                 	sku_value = "";
                 	if(category_id != null)
                 	{
                 		itemCat = Item_Category[ID == category_id];
                 		if(itemCat.ID != null)
                 		{
                 			catCode = itemCat.Category_Code;
                 			nextNum = itemCat.Next_Number;
                 			if(catCode != null && nextNum != null)
                 			{
                 				// Convert number to string
                 				numStr = nextNum.toString();
                 				// Manual padding to 4 digits (0001, 0002, etc.)
                 				if(numStr.length() == 1)
                 				{
                 					numStr = "000" + numStr;
                 				}
                 				else if(numStr.length() == 2)
                 				{
                 					numStr = "00" + numStr;
                 				}
                 				else if(numStr.length() == 3)
                 				{
                 					numStr = "0" + numStr;
                 				}
                 				// 4+ digits: leave as is
                 				// Build SKU: CODE-0001
                 				sku_value = catCode + "-" + numStr;
                 				// ✅ Correct Zoho update syntax
                 				update Item_Category[ID == itemCat.ID]
                 				[
                 					Next_Number=nextNum + 1
                 				];
                 			}
                 		}
                 	}
                 	return sku_value;
                 }

