map po.recalculate_po_line(int item_id, int selected_uom, float quantity_ordered, float unit_cost)
{
                 	// Default result
                 	result = Map();
                 	result.put("qty_in_base",null);
                 	result.put("line_total",null);
                 	result.put("display_uom_name",null);
                 	result.put("conversion_factor",1.0);
                 	// Guard: no item
                 	if(item_id == null)
                 	{
                 		return result;
                 	}
                 	item_rec = Items_Register[ID == item_id];
                 	if(item_rec.ID == null)
                 	{
                 		return result;
                 	}
                 	base_uom = item_rec.Base_Unit_Of_Measure;
                 	conversion_factor = 1.0;
                 	// UoM display name
                 	if(selected_uom != null)
                 	{
                 		uom_rec = Unit_Of_Measure[ID == selected_uom];
                 		if(uom_rec.ID != null)
                 		{
                 			result.put("display_uom_name",uom_rec.Unit_Of_Measure_Name);
                 		}
                 	}
                 	// If selected UoM is different from base, try get conversion
                 	if(selected_uom != null && selected_uom != base_uom)
                 	{
                 		conv = Unit_Of_Measure_Conversion[Item == item_rec.ID && Base_Unit_Of_Measure == base_uom && Alternate_Unit_Of_Measure == selected_uom];
                 		if(conv.count() > 0)
                 		{
                 			conversion_factor = conv.Conversion_Factor;
                 		}
                 		// else leave conversion_factor = 1.0
                 	}
                 	result.put("conversion_factor",conversion_factor);
                 	// Calculate Qty in base
                 	if(quantity_ordered != null && quantity_ordered > 0)
                 	{
                 		qty_base = quantity_ordered * conversion_factor;
                 		result.put("qty_in_base",qty_base);
                 		// ❗ Line total should use Quantity Ordered, NOT qty_base
                 		if(unit_cost != null && unit_cost >= 0)
                 		{
                 			result.put("line_total",quantity_ordered * unit_cost);
                 		}
                 	}
                 	return result;
                 }

map po.receive_po_detail_from_CleanSand(string po_number, date po_date, string employee_voucher, string po_detail_number, float qty_received, float unit_cost)
{
                 	result = Map();
                 	result.put("ok",false);
                 	result.put("message","");
                 	po_number_text = ifnull(po_number,"").trim();
                 	employee_voucher_text = ifnull(employee_voucher,"").trim();
                 	po_detail_number_text = ifnull(po_detail_number,"").trim();
                 	if(po_number_text == "")
                 	{
                 		result.put("message","PO Number was not provided.");
                 		return result;
                 	}
                 	if(po_date == null)
                 	{
                 		result.put("message","PO Date was not provided.");
                 		return result;
                 	}
                 	if(employee_voucher_text == "")
                 	{
                 		result.put("message","Employee Voucher was not provided.");
                 		return result;
                 	}
                 	if(po_detail_number_text == "")
                 	{
                 		result.put("message","PO Detail Number was not provided.");
                 		return result;
                 	}
                 	po_rec = Purchase_Order[PO_Number == po_number_text && PO_Date == po_date && Employee_Voucher == employee_voucher_text];
                 	if(po_rec.ID == null)
                 	{
                 		result.put("message","Matching Store PO was not found for PO Number " + po_number_text + ", PO Date " + po_date.toString("dd-MMM-yyyy") + " and Employee Voucher " + employee_voucher_text + ".");
                 		return result;
                 	}
                 	det_rec = Purchase_Order_Details[Purchase_Order == po_rec.ID && Purchase_Order_Details_Number == po_detail_number_text];
                 	if(det_rec.ID == null)
                 	{
                 		result.put("message","Matching Store PO Detail was not found for detail number " + po_detail_number_text + ".");
                 		return result;
                 	}
                 	received_now = ifnull(qty_received,0.0);
                 	if(received_now < 0)
                 	{
                 		result.put("message","Quantity Received cannot be negative.");
                 		return result;
                 	}
                 	old_received = ifnull(det_rec.Quantity_Received,0.0);
                 	quantity_ordered = ifnull(det_rec.Quantity_Ordered,0.0);
                 	new_received = old_received + received_now;
                 	det_rec.Quantity_Received=new_received;
                 	quantity_remaining = quantity_ordered - new_received;
                 	if(quantity_remaining < 0)
                 	{
                 		quantity_remaining = 0.0;
                 	}
                 	det_rec.Quantity_Remaining=quantity_remaining;
                 	if(new_received <= 0)
                 	{
                 		det_rec.Receiving_Status="Not Received";
                 	}
                 	else if(new_received >= quantity_ordered)
                 	{
                 		det_rec.Receiving_Status="Fully Received";
                 	}
                 	else
                 	{
                 		det_rec.Receiving_Status="Partially Received";
                 	}
                 	det_rec.Quantity_Billable=new_received;
                 	quantity_unbilled = new_received - ifnull(det_rec.Quantity_Billed,0.0);
                 	if(quantity_unbilled < 0)
                 	{
                 		quantity_unbilled = 0.0;
                 	}
                 	det_rec.Quantity_Unbilled=quantity_unbilled;
                 	led = Store_Item_Stock[Item == det_rec.Item && Store == det_rec.From_Store && Stock_Condition == det_rec.Stock_Condition];
                 	if(led.ID != null)
                 	{
                 		led.Default_Cost=ifnull(unit_cost,0.0);
                 	}
                 	thisapp.po.update_po_receiving_status(po_rec.ID);
                 	result.put("ok",true);
                 	result.put("purchase_order_id",po_rec.ID);
                 	result.put("purchase_order_detail_id",det_rec.ID);
                 	result.put("quantity_received",new_received);
                 	result.put("quantity_remaining",quantity_remaining);
                 	result.put("message","Store PO Detail, Store Item Stock cost, and PO Header were updated from Clean Sand Management.");
                 	return result;
                 }

map po.receive_po_detail_from_concrete(string po_number, date po_date, int company_id, string po_detail_number, float qty_received, float unit_cost)
{
                 	result = Map();
                 	result.put("ok",false);
                 	result.put("message","");
                 	po_rec = Purchase_Order[PO_Number == po_number && PO_Date == po_date && Company == company_id];
                 	if(po_rec.ID == null)
                 	{
                 		result.put("message","Matching Store PO not found.");
                 		return result;
                 	}
                 	det_rec = Purchase_Order_Details[Purchase_Order == po_rec.ID && Purchase_Order_Details_Number == po_detail_number];
                 	if(det_rec.ID == null)
                 	{
                 		result.put("message","Matching Store PO Detail not found.");
                 		return result;
                 	}
                 	new_received = ifnull(det_rec.Quantity_Received,0.0) + ifnull(qty_received,0.0);
                 	det_rec.Quantity_Received=new_received;
                 	det_rec.Quantity_Remaining=ifnull(det_rec.Quantity_Ordered,0.0) - new_received;
                 	if(det_rec.Quantity_Remaining < 0)
                 	{
                 		det_rec.Quantity_Remaining=0.0;
                 	}
                 	if(new_received <= 0)
                 	{
                 		det_rec.Receiving_Status="Not Received";
                 	}
                 	else if(new_received >= ifnull(det_rec.Quantity_Ordered,0.0))
                 	{
                 		det_rec.Receiving_Status="Fully Received";
                 	}
                 	else
                 	{
                 		det_rec.Receiving_Status="Partially Received";
                 	}
                 	det_rec.Quantity_Billable=new_received;
                 	det_rec.Quantity_Unbilled=new_received - ifnull(det_rec.Quantity_Billed,0.0);
                 	if(det_rec.Quantity_Unbilled < 0)
                 	{
                 		det_rec.Quantity_Unbilled=0.0;
                 	}
                 	// Update Store Item Stock Default Cost
                 	led = Store_Item_Stock[Item == det_rec.Item && Store == det_rec.From_Store && Stock_Condition == det_rec.Stock_Condition];
