                 	}
                 	if(employee_voucher == "")
                 	{
                 		result.put("message","Employee Voucher is required.");
                 		return result;
                 	}
                 	if(po_detail_number == "")
                 	{
                 		result.put("message","PO Detail Number is required.");
                 		return result;
                 	}
                 	po_rec = Purchase_Order[PO_Number == po_number && PO_Date == po_date && Employee_Voucher == employee_voucher];
                 	if(po_rec.ID == null)
                 	{
                 		result.put("message","Matching Store PO not found for " + employee_voucher + " - " + po_number);
                 		return result;
                 	}
                 	det_rec = Purchase_Order_Details[Purchase_Order == po_rec.ID && Purchase_Order_Details_Number == po_detail_number];
                 	if(det_rec.ID == null)
                 	{
                 		result.put("message","Matching Store PO Detail not found: " + po_detail_number);
                 		return result;
                 	}
                 	received_now = ifnull(qty_received,0.0);
                 	new_received = ifnull(det_rec.Quantity_Received,0.0) + received_now;
                 	det_rec.Quantity_Received=new_received;
                 	det_rec.Quantity_Remaining=ifnull(det_rec.Quantity_Ordered,0.0) - new_received;
                 	if(det_rec.Quantity_Remaining < 0)
                 	{
                 		det_rec.Quantity_Remaining=0.0;
                 	}
                 	if(new_received <= 0)
                 	{
                 		det_rec.Receiving_Status="Not Received";
                 	}
                 	else if(new_received >= ifnull(det_rec.Quantity_Ordered,0.0))
                 	{
                 		det_rec.Receiving_Status="Fully Received";
                 	}
                 	else
                 	{
                 		det_rec.Receiving_Status="Partially Received";
                 	}
                 	det_rec.Quantity_Billable=new_received;
                 	det_rec.Quantity_Unbilled=new_received - ifnull(det_rec.Quantity_Billed,0.0);
                 	if(det_rec.Quantity_Unbilled < 0)
                 	{
                 		det_rec.Quantity_Unbilled=0.0;
                 	}
                 	if(det_rec.Item != null && det_rec.From_Store != null && det_rec.Stock_Condition != null)
                 	{
                 		led = Store_Item_Stock[Item == det_rec.Item && Store == det_rec.From_Store && Stock_Condition == det_rec.Stock_Condition];
                 		if(led.ID != null)
                 		{
                 			led.Default_Cost=ifnull(unit_cost,0.0);
                 		}
                 	}
                 	thisapp.po.update_po_receiving_status(po_rec.ID);
                 	result.put("ok",true);
                 	result.put("message","Store PO Detail, stock cost, and PO header updated from Masaka Site Management.");
                 	return result;
                 }

string po.receive_po_line(int po_detail_id, float qty_to_receive, string srv_number, int store_id, string display_name_store, int uom_id, string stock_condition, float unit_cost_base)
{
                 	msg = "";
                 	info "DEBUG receive_po_line: START";
                 	// =====================================================
                 	// 1. BASIC VALIDATION
                 	// =====================================================
                 	if(po_detail_id == null)
                 	{
                 		info "DEBUG receive_po_line: po_detail_id is null";
                 		return "No Purchase Order Detail specified.";
                 	}
                 	if(qty_to_receive == null || qty_to_receive <= 0)
                 	{
                 		info "DEBUG receive_po_line: qty_to_receive invalid = " + ifnull(qty_to_receive,0.0).toString();
                 		return "Quantity to receive must be greater than zero.";
                 	}
                 	if(store_id == null)
                 	{
                 		info "DEBUG receive_po_line: store_id is null";
                 		return "Receiving Store is required.";
                 	}
                 	// =====================================================
                 	// 2. NORMALIZE VALUES
                 	// =====================================================
                 	cond = ifnull(stock_condition,"New").trim();
                 	if(cond == "")
                 	{
                 		cond = "New";
                 	}
                 	receiving_store_display = ifnull(display_name_store,"").trim();
                 	if(unit_cost_base == null || unit_cost_base < 0)
                 	{
                 		unit_cost_base = 0.0;
                 	}
                 	info "DEBUG receive_po_line: po_detail_id = " + po_detail_id.toString();
                 	info "DEBUG receive_po_line: qty_to_receive = " + qty_to_receive.toString();
                 	info "DEBUG receive_po_line: store_id = " + store_id.toString();
                 	info "DEBUG receive_po_line: receiving_store_display = " + receiving_store_display;
                 	info "DEBUG receive_po_line: uom_id = " + ifnull(uom_id,0).toString();
                 	info "DEBUG receive_po_line: unit_cost_base = " + unit_cost_base.toString();
                 	info "DEBUG receive_po_line: cond = " + cond;
                 	// =====================================================
                 	// 3. LOAD PURCHASE ORDER DETAIL
                 	// =====================================================
                 	po_det = Purchase_Order_Details[ID == po_detail_id];
                 	if(po_det.ID == null)
                 	{
                 		info "DEBUG receive_po_line: po_det not found";
                 		return "Purchase Order Detail not found.";
                 	}
                 	item_id = po_det.Item;
                 	if(item_id == null)
                 	{
                 		info "DEBUG receive_po_line: po_det.Item is null";
                 		return "PO line has no Item. Cannot receive.";
                 	}
                 	info "DEBUG receive_po_line: po_det.ID = " + po_det.ID.toString();
                 	info "DEBUG receive_po_line: item_id = " + item_id.toString();
                 	info "DEBUG receive_po_line: po_det.Unit_Cost = " + ifnull(po_det.Unit_Cost,0.0).toString();
                 	// =====================================================
                 	// 4. PURCHASE ORDER QUANTITIES
                 	// =====================================================
                 	qty_ordered = ifnull(po_det.Quantity_Ordered,0.0);
                 	qty_received = ifnull(po_det.Quantity_Received,0.0);
                 	qty_remaining = ifnull(po_det.Quantity_Remaining,qty_ordered - qty_received);
                 	if(qty_remaining < 0)
                 	{
                 		qty_remaining = 0.0;
                 	}
                 	info "DEBUG receive_po_line: qty_ordered = " + qty_ordered.toString();
                 	info "DEBUG receive_po_line: qty_received = " + qty_received.toString();
                 	info "DEBUG receive_po_line: qty_remaining = " + qty_remaining.toString();
                 	if(qty_to_receive > qty_remaining)
                 	{
                 		info "DEBUG receive_po_line: over-receive blocked";
                 		return "Cannot receive more than remaining. Remaining: " + qty_remaining.toString();
                 	}
                 	// =====================================================
                 	// 5. DETERMINE INTERNAL TRANSFER
                 	// =====================================================
                 	is_internal = false;
                 	from_store_id = null;
                 	from_store_display = "";
                 	if(po_det.From_Store != null)
                 	{
                 		from_store_id = po_det.From_Store;
                 		from_store_display = ifnull(po_det.Display_Name_From_Store,"").trim();
                 		if(store_id != null && from_store_id != store_id)
                 		{
                 			is_internal = true;
                 		}
                 	}
                 	info "DEBUG receive_po_line: is_internal = " + is_internal.toString();
                 	info "DEBUG receive_po_line: from_store_id = " + ifnull(from_store_id,0).toString();
                 	info "DEBUG receive_po_line: from_store_display = " + from_store_display;
                 	// =====================================================
                 	// 6. RESOLVE UNIT OF MEASURE
                 	// =====================================================
                 	selected_uom = uom_id;
                 	if(selected_uom == null)
                 	{
                 		selected_uom = po_det.Unit_Of_Measure;
                 	}
                 	if(selected_uom != null)
                 	{
                 		info "DEBUG receive_po_line: selected_uom = " + selected_uom.toString();
                 	}
                 	else
                 	{
                 		info "DEBUG receive_po_line: selected_uom is null";
                 		return "Unit Of Measure is required.";
                 	}
                 	// =====================================================
                 	// 7. CONVERT TO BASE QUANTITY
                 	// =====================================================
                 	base_qty = thisapp.uom.convert_to_base_qty(item_id,selected_uom,qty_to_receive);
                 	info "DEBUG receive_po_line: base_qty = " + ifnull(base_qty,0.0).toString();
                 	if(base_qty == null || base_qty <= 0)
                 	{
                 		info "DEBUG receive_po_line: base_qty invalid";
                 		return "Base quantity conversion failed. Check Unit Of Measure conversion.";
                 	}
                 	// =====================================================
                 	// 8. INTERNAL TRANSFER — STOCK OUT FROM SOURCE STORE
                 	// =====================================================
                 	if(is_internal && from_store_id != null && base_qty > 0)
                 	{
                 		info "DEBUG receive_po_line: posting internal stock out";
                 		source_reference = ifnull(po_det.Purchase_Order_Details_Number,po_det.ID.toString()).toString();
                 		thisapp.stock.log_stock_transaction(item_id,base_qty,"Stock Out","Internal Transfer",source_reference,from_store_id,from_store_display,cond,0.0,"Purchase_Order_Details",po_det.ID);
                 	}
                 	// =====================================================
                 	// 9. STOCK IN TO RECEIVING STORE
                 	// =====================================================
                 	if(base_qty > 0 && store_id != null)
                 	{
                 		receiving_reference = ifnull(srv_number,"").trim();
                 		if(receiving_reference == "")
                 		{
                 			receiving_reference = po_det.ID.toString();
                 		}
                 		info "DEBUG receive_po_line: posting stock in with cost = " + unit_cost_base.toString();
                 		thisapp.stock.log_stock_transaction(item_id,base_qty,"Stock In","Stock Receiving Voucher",receiving_reference,store_id,receiving_store_display,cond,unit_cost_base,"Stock Receiving Details",po_det.ID);
                 	}
                 	// =====================================================
                 	// 10. STORE-LEVEL COSTING
                 	// =====================================================
                 	if(store_id != null && base_qty > 0)
                 	{
                 		led = Store_Item_Stock[Item == item_id && Store == store_id && Stock_Condition == cond];
                 		info "DEBUG receive_po_line: ledger found = " + if(led.ID != null,"yes","no");
                 		if(led.ID != null)
                 		{
                 			// Ensure display names are filled
                 			item_rec_display = Items_Register[ID == item_id];
                 			if(item_rec_display.ID != null)
                 			{
                 				display_item = ifnull(item_rec_display.Item_Name,"").trim();
                 				display_sku = ifnull(item_rec_display.SKU,"").trim();
                 				if(display_sku != "")
                 				{
                 					if(display_item != "")
                 					{
                 						display_item = display_item + " - " + display_sku;
                 					}
                 					else
                 					{
                 						display_item = display_sku;
                 					}
                 				}
                 				led.Display_Name_Item=display_item;
                 			}
                 			led.Display_Name_Store=receiving_store_display;
                 			current_qty = ifnull(led.Qty_On_Hand,0.0);
                 			old_qty = current_qty - base_qty;
                 			if(old_qty < 0)
                 			{
                 				old_qty = 0.0;
                 			}
                 			old_avg = ifnull(led.Average_Cost,0.0);
                 			new_avg = old_avg;
                 			info "DEBUG receive_po_line: current_qty = " + current_qty.toString();
                 			info "DEBUG receive_po_line: old_qty = " + old_qty.toString();
                 			info "DEBUG receive_po_line: old_avg = " + old_avg.toString();
                 			if(unit_cost_base > 0)
                 			{
                 				if(old_qty <= 0)
                 				{
                 					new_avg = unit_cost_base;
                 				}
                 				else
                 				{
                 					new_avg = (old_qty * old_avg + base_qty * unit_cost_base) / (old_qty + base_qty);
                 				}
                 				info "DEBUG receive_po_line: writing Default_Cost = " + unit_cost_base.toString();
                 				info "DEBUG receive_po_line: writing Average_Cost = " + new_avg.toString();
                 				led.Default_Cost=unit_cost_base;
                 				led.Average_Cost=new_avg;
                 			}
                 			else
                 			{
                 				info "DEBUG receive_po_line: unit_cost_base not > 0, skipping cost write";
                 			}
                 			stock_cost = ifnull(led.Average_Cost,ifnull(led.Default_Cost,0.0));
                 			led.Stock_Value=(ifnull(led.Qty_On_Hand,0.0) * stock_cost).round(2);
                 			led.Last_Updated=zoho.currenttime;
                 			info "DEBUG receive_po_line: stock_cost = " + stock_cost.toString();
                 			info "DEBUG receive_po_line: Stock_Value = " + ifnull(led.Stock_Value,0.0).toString();
                 		}
                 	}
                 	// =====================================================
                 	// 11. OPTIONAL GLOBAL ITEM COSTING
                 	// =====================================================
                 	if(unit_cost_base > 0)
                 	{
                 		item_rec = Items_Register[ID == item_id];
                 		if(item_rec.ID != null)
                 		{
                 			item_rec.Default_Cost=unit_cost_base;
                 			info "DEBUG receive_po_line: item_rec.Default_Cost updated to " + unit_cost_base.toString();
                 		}
                 	}
                 	// =====================================================
                 	// 12. UPDATE PO DETAIL QUANTITIES
                 	// =====================================================
                 	new_qty_received = qty_received + qty_to_receive;
                 	new_qty_remaining = qty_ordered - new_qty_received;
                 	if(new_qty_remaining < 0)
                 	{
                 		new_qty_remaining = 0.0;
                 	}
                 	po_det.Quantity_Received=new_qty_received;
                 	po_det.Quantity_Remaining=new_qty_remaining;
                 	if(new_qty_received <= 0)
                 	{
                 		po_det.Receiving_Status="Not Received";
                 	}
                 	else if(new_qty_remaining > 0)
                 	{
                 		po_det.Receiving_Status="Partially Received";
                 	}
                 	else
                 	{
                 		po_det.Receiving_Status="Fully Received";
                 	}
                 	// =====================================================
                 	// 13. UPDATE BILLABLE / UNBILLED
                 	// =====================================================
                 	po_det.Quantity_Billable=ifnull(po_det.Quantity_Billable,0.0) + qty_to_receive;
                 	if(po_det.Quantity_Billable < 0)
                 	{
                 		po_det.Quantity_Billable=0.0;
                 	}
                 	po_det.Quantity_Unbilled=ifnull(po_det.Quantity_Billable,0.0) - ifnull(po_det.Quantity_Billed,0.0);
                 	if(po_det.Quantity_Unbilled < 0)
                 	{
                 		po_det.Quantity_Unbilled=0.0;
                 	}
                 	// =====================================================
                 	// 14. RESPONSE
                 	// =====================================================
                 	msg = "Received " + qty_to_receive.toString() + " units for PO Detail ID: " + po_detail_id.toString();
                 	info "DEBUG receive_po_line: END";
                 	return msg;
                 }

map po.syncPurchaseOrderFromCleanSand(map payload)
{
                 	result = Map();
                 	result.put("ok",false);
                 	result.put("message","");
                 	result.put("store_po_id",null);
                 	// =====================================================
                 	// 1. GET AND VALIDATE SOURCE DETAILS
                 	// =====================================================
                 	source_id = payload.get("Source_Record_ID");
                 	source_form = ifnull(payload.get("Source_Form"),"").trim();
                 	if(source_id == null)
                 	{
                 		result.put("message","Source_Record_ID is missing.");
                 		return result;
                 	}
                 	if(source_form == "")
                 	{
                 		source_form = "Clean Sand Management - Purchase Order";
                 	}
                 	// =====================================================
                 	// 2. FIND EXISTING STORE PURCHASE ORDER
                 	// =====================================================
                 	store_po = Purchase_Order[Source_Record_ID == source_id && Source_Form == source_form];
                 	// =====================================================
                 	// 3. CREATE STORE PURCHASE ORDER
                 	// =====================================================
                 	if(store_po.ID == null)
                 	{
                 		store_po_id = insert into Purchase_Order
                 		[
                 			PO_Type=ifnull(payload.get("PO_Type"),"External Purchase")
                 			Employee_Voucher=payload.get("Employee_Voucher")
                 			Site=payload.get("Site")
                 			PO_Number=payload.get("PO_Number")
                 			PO_Date=payload.get("PO_Date")
                 			Receive_Status=payload.get("Receive_Status")
                 			PO_Status=payload.get("PO_Status")
                 			PO_Total=ifnull(payload.get("PO_Total"),0.0)
                 			Bill_Status=payload.get("Bill_Status")
                 			PO_Billed_Total=ifnull(payload.get("PO_Billed_Total"),0.0)
                 			Payment_Status=payload.get("Payment_Status")
                 			PO_Total_Paid=ifnull(payload.get("PO_Total_Paid"),0.0)
                 			Source_Record_ID=source_id
                 			Source_Form=source_form
                 			Added_User=zoho.loginuser
                 		];
                 		store_po = Purchase_Order[ID == store_po_id];
                 	}
                 	// =====================================================
                 	// 4. UPDATE EXISTING STORE PURCHASE ORDER
                 	// =====================================================
                 	else
                 	{
                 		store_po.PO_Type=ifnull(payload.get("PO_Type"),"External Purchase");
                 		store_po.Employee_Voucher=payload.get("Employee_Voucher");
                 		store_po.Site=payload.get("Site");
                 		store_po.PO_Number=payload.get("PO_Number");
                 		store_po.PO_Date=payload.get("PO_Date");
                 		store_po.Receive_Status=payload.get("Receive_Status");
                 		store_po.PO_Status=payload.get("PO_Status");
                 		store_po.PO_Total=ifnull(payload.get("PO_Total"),0.0);
                 		store_po.Bill_Status=payload.get("Bill_Status");
                 		store_po.PO_Billed_Total=ifnull(payload.get("PO_Billed_Total"),0.0);
                 		store_po.Payment_Status=payload.get("Payment_Status");
                 		store_po.PO_Total_Paid=ifnull(payload.get("PO_Total_Paid"),0.0);
                 		store_po.Source_Form=source_form;
                 	}
                 	// =====================================================
                 	// 5. VERIFY PURCHASE ORDER WAS CREATED OR FOUND
                 	// =====================================================
                 	if(store_po.ID == null)
                 	{
                 		result.put("message","The Store Purchase Order could not be created or found.");
                 		return result;
                 	}
                 	// =====================================================
                 	// 6. REMOVE OLD PURCHASE ORDER DETAILS
                 	// =====================================================
                 	delete from Purchase_Order_Details[Purchase_Order == store_po.ID];
                 	// =====================================================
                 	// 7. INSERT CURRENT PURCHASE ORDER DETAILS
                 	// =====================================================
                 	lines = payload.get("Lines");
                 	if(lines != null)
                 	{
                 		for each  line in lines
                 		{
                 			if(line != null)
                 			{
                 				insert into Purchase_Order_Details
                 				[
                 					Purchase_Order=store_po.ID
                 					Display_Name_Purchase_Order=line.get("Display_Name_Purchase_Order")
                 					Purchase_Order_Number=line.get("Purchase_Order_Number")
                 					Purchase_Order_Details_Number=line.get("Purchase_Order_Details_Number")
                 					Item=line.get("Item")
                 					Display_Name_Item=line.get("Display_Name_Item")
                 					Stock_Condition=line.get("Stock_Condition")
                 					Quantity_Ordered=ifnull(line.get("Quantity_Ordered"),0.0)
                 					Unit_Of_Measure=line.get("Unit_Of_Measure")
                 					Display_Name_Unit_Of_Measure=line.get("Display_Name_Unit_Of_Measure")
                 					Unit_Cost=ifnull(line.get("Unit_Cost"),0.0)
                 					Line_Total=ifnull(line.get("Line_Total"),0.0)
                 					Quantity_in_Base_Unit_Of_Measure=ifnull(line.get("Quantity_in_Base_Unit_Of_Measure"),0.0)
                 					Quantity_Received=ifnull(line.get("Quantity_Received"),0.0)
                 					Quantity_Remaining=ifnull(line.get("Quantity_Remaining"),0.0)
                 					Receiving_Status=line.get("Receiving_Status")
                 					Quantity_Billable=ifnull(line.get("Quantity_Billable"),0.0)
                 					Quantity_Billed=ifnull(line.get("Quantity_Billed"),0.0)
                 					Quantity_Unbilled=ifnull(line.get("Quantity_Unbilled"),0.0)
                 					Billing_Status=line.get("Billing_Status")
                 					Added_User=zoho.loginuser
                 				]
                 			}
                 		}
                 	}
                 	// =====================================================
                 	// 8. RETURN SUCCESS
                 	// =====================================================
                 	result.put("ok",true);
                 	result.put("message","Purchase Order synced to Store Management from Clean Sand Management.");
                 	result.put("store_po_id",store_po.ID);
                 	return result;
                 }

