                 	if(po_number == "")
                 	{
                 		result.put("message","PO Number is required.");
                 		return result;
                 	}
                 	if(po_date == null)
                 	{
                 		result.put("message","PO Date is required.");
                 		return result;
                 	}
                 	if(employee_voucher == "")
                 	{
                 		result.put("message","Employee Voucher is required.");
                 		return result;
                 	}
                 	// =====================================================
                 	// 1. FIND MATCHING PURCHASE ORDER
                 	// =====================================================
                 	po_rec = null;
                 	for each  rec in Purchase_Order[PO_Number == po_number && PO_Date == po_date]
                 	{
                 		stored_employee_voucher = ifnull(rec.Employee_Voucher,"").trim();
                 		if(stored_employee_voucher == employee_voucher)
                 		{
                 			po_rec = rec;
                 			break;
                 		}
                 	}
                 	if(po_rec == null || po_rec.ID == null)
                 	{
                 		result.put("message","Matching Store Purchase Order not found. " + "PO Number: " + po_number + ", PO Date: " + po_date.toString("dd-MMM-yyyy") + ", Employee Voucher: " + employee_voucher);
                 		return result;
                 	}
                 	po_total = round(ifnull(po_rec.PO_Total,0.0),2);
                 	// =====================================================
                 	// 2. UPDATE BILLING TOTALS
                 	// =====================================================
                 	billed_total = round(ifnull(po_billed_total,0.0),2);
                 	if(billed_total < 0)
                 	{
                 		billed_total = 0.0;
                 	}
                 	if(po_total > 0 && billed_total > po_total)
                 	{
                 		billed_total = po_total;
                 	}
                 	po_rec.PO_Billed_Total=billed_total;
                 	if(billed_total <= 0)
                 	{
                 		po_rec.Bill_Status="Not Billed";
                 	}
                 	else if(po_total > 0 && billed_total < po_total)
                 	{
                 		po_rec.Bill_Status="Partially Billed";
                 	}
                 	else
                 	{
                 		po_rec.Bill_Status="Billed";
                 	}
                 	// =====================================================
                 	// 3. UPDATE PAYMENT TOTALS
                 	// =====================================================
                 	total_paid = round(ifnull(po_total_paid,0.0),2);
                 	if(total_paid < 0)
                 	{
                 		total_paid = 0.0;
                 	}
                 	if(po_total > 0 && total_paid > po_total)
                 	{
                 		total_paid = po_total;
                 	}
                 	po_rec.PO_Total_Paid=total_paid;
                 	if(po_total <= 0)
                 	{
                 		po_rec.Payment_Status="Not Payable";
                 	}
                 	else if(total_paid <= 0)
                 	{
                 		po_rec.Payment_Status="Not Paid";
                 	}
                 	else if(total_paid < po_total)
                 	{
                 		po_rec.Payment_Status="Partially Paid";
                 	}
                 	else
                 	{
                 		po_rec.Payment_Status="Paid";
                 	}
                 	// =====================================================
                 	// 4. CLOSE PURCHASE ORDER WHEN FULLY BILLED AND PAID
                 	// =====================================================
                 	if(po_rec.Bill_Status == "Billed" && po_rec.Payment_Status == "Paid")
                 	{
                 		po_rec.PO_Status="Closed";
                 	}
                 	// =====================================================
                 	// 5. RESPONSE
                 	// =====================================================
                 	result.put("ok",true);
                 	result.put("message","Store PO billing and payment statuses updated.");
                 	result.put("record_id",po_rec.ID);
                 	result.put("PO_Billed_Total",po_rec.PO_Billed_Total);
                 	result.put("Bill_Status",po_rec.Bill_Status);
                 	result.put("PO_Total_Paid",po_rec.PO_Total_Paid);
                 	result.put("Payment_Status",po_rec.Payment_Status);
                 	result.put("PO_Status",po_rec.PO_Status);
                 	return result;
                 }

void po.update_po_receiving_status(int po_id)
{
                 	if(po_id == null)
                 	{
                 		return;
                 	}
                 	po_rec = Purchase_Order[ID == po_id];
                 	if(po_rec.ID == null)
                 	{
                 		return;
                 	}
                 	det_list = Purchase_Order_Details[Purchase_Order == po_id];
                 	has_lines = false;
                 	any_received = false;
                 	all_fully_received = true;
                 	any_billed = false;
                 	all_fully_billed = true;
                 	po_total_paid = 0.0;
                 	paid_bill_map = Map();
                 	for each  det in det_list
                 	{
                 		has_lines = true;
                 		rec_status = ifnull(det.Receiving_Status,"Not Received");
                 		if(rec_status == "Fully Received" || rec_status == "Partially Received")
                 		{
                 			any_received = true;
                 		}
                 		if(rec_status != "Fully Received")
                 		{
                 			all_fully_received = false;
                 		}
                 		bill_status = ifnull(det.Billing_Status,"Not Billed");
                 		if(bill_status == "Fully Billed" || bill_status == "Partially Billed")
                 		{
                 			any_billed = true;
                 		}
                 		if(bill_status != "Fully Billed")
                 		{
                 			all_fully_billed = false;
                 		}
                 	}
                 	if(!has_lines)
                 	{
                 		po_rec.Receive_Status="Not Received";
                 		po_rec.Bill_Status="Not Billed";
                 		po_rec.PO_Total_Paid=0.0;
                 		po_rec.Payment_Status="Not Paid";
                 		if(po_rec.PO_Status != "Cancelled")
                 		{
                 			po_rec.PO_Status="Open";
                 		}
                 		return;
                 	}
                 	// =========================
                 	// RECEIVING STATUS
                 	// =========================
                 	if(all_fully_received == true)
                 	{
                 		po_rec.Receive_Status="Fully Received";
                 	}
                 	else if(any_received == true)
                 	{
                 		po_rec.Receive_Status="Partially Received";
                 	}
                 	else
                 	{
                 		po_rec.Receive_Status="Not Received";
                 	}
                 	// =========================
                 	// BILL STATUS
                 	// Purchase Order values:
                 	// Not Billed, Partially Billed, Billed
                 	// =========================
                 	if(all_fully_billed == true)
                 	{
                 		po_rec.Bill_Status="Billed";
                 	}
                 	else if(any_billed == true)
                 	{
                 		po_rec.Bill_Status="Partially Billed";
                 	}
                 	else
                 	{
                 		po_rec.Bill_Status="Not Billed";
                 	}
                 	// =========================
                 	// PAYMENT TOTAL FROM BILLS
                 	// =========================
                 	bill_rows = Bill_Details[Item.Purchase_Order == po_rec.ID];
                 	for each  bd in bill_rows
                 	{
                 		if(bd.Bill != null)
                 		{
                 			bill_rec = Bill[ID == bd.Bill];
                 			if(bill_rec.ID != null)
                 			{
                 				bill_key = bill_rec.ID.toString();
                 				if(paid_bill_map.get(bill_key) == null)
                 				{
                 					paid_bill_map.put(bill_key,bill_rec.ID);
                 					po_total_paid = round(po_total_paid + ifnull(bill_rec.Amount_Paid,0.0),2);
                 				}
                 			}
                 		}
                 	}
                 	po_rec.PO_Total_Paid=round(po_total_paid,2);
                 	// =========================
                 	// PAYMENT STATUS
                 	// =========================
                 	po_total = round(ifnull(po_rec.PO_Total,0.0),2);
                 	if(po_total_paid <= 0)
                 	{
                 		po_rec.Payment_Status="Not Paid";
                 	}
                 	else if(po_total_paid < po_total)
                 	{
                 		po_rec.Payment_Status="Partially Paid";
                 	}
                 	else
                 	{
                 		po_rec.Payment_Status="Paid";
                 	}
                 	// =========================
                 	// PO STATUS
                 	// =========================
                 	if(all_fully_received == true && all_fully_billed == true && po_rec.Payment_Status == "Paid")
                 	{
                 		po_rec.PO_Status="Closed";
                 	}
                 	else
                 	{
                 		if(po_rec.PO_Status != "Cancelled")
                 		{
                 			po_rec.PO_Status="Open";
                 		}
                 	}
                 	// =========================
                 	// PO STATUS
                 	// =========================
                 	if(all_fully_received == true && all_fully_billed == true && po_rec.Payment_Status == "Paid")
                 	{
                 		po_rec.PO_Status="Closed";
                 	}
                 	else
                 	{
                 		if(po_rec.PO_Status != "Cancelled")
                 		{
                 			po_rec.PO_Status="Open";
                 		}
                 	}
                 	// =========================
                 	// SYNC STATUS TO CONCRETE
                 	// =========================
                 	if(po_rec.PO_Number != null && po_rec.PO_Date != null && po_rec.Company != null)
                 	{
                 		sync_result = concrete_products_management.po.sync_po_status_from_store(po_rec.PO_Number,po_rec.PO_Date,po_rec.Company.ID,po_rec.PO_Status);
                 		info sync_result;
                 	}
                 }

map po.update_po_receiving_status_from_masaka_site_management(string po_number, date po_date, int company_id, decimal po_billed_total, string bill_status)
{
                 	result = Map();
                 	result.put("ok",false);
                 	result.put("message","");
                 	po_rec = Purchase_Order[PO_Number == po_number && PO_Date == po_date && Company == company_id];
                 	if(po_rec.ID == null)
                 	{
                 		result.put("message","Matching Store Purchase Order not found.");
                 		return result;
                 	}
                 	po_rec.PO_Billed_Total=ifnull(po_billed_total,0.0);
                 	po_rec.Bill_Status=ifnull(bill_status,"Not Billed");
                 	thisapp.po.update_po_receiving_status(po_rec.ID);
                 	result.put("ok",true);
                 	result.put("message","Store PO billing and statuses updated from Masaka Site Management.");
                 	result.put("PO_Billed_Total",po_rec.PO_Billed_Total);
                 	result.put("Bill_Status",po_rec.Bill_Status);
                 	result.put("PO_Status",po_rec.PO_Status);
                 	result.put("Receive_Status",po_rec.Receive_Status);
                 	result.put("Payment_Status",po_rec.Payment_Status);
                 	return result;
                 }

void stock.adjust_item_stock(int item_id, float qty_change, string stock_condition)
{
                 	if(item_id == null || qty_change == null)
                 	{
                 		return;
                 	}
                 	item_rec = Items_Register[ID == item_id];
                 	if(item_rec.ID == null)
                 	{
                 		return;
                 	}
                 	item_rec.Stock_On_Hand=ifnull(item_rec.Stock_On_Hand,0.0) + qty_change;
                 	cond = ifnull(stock_condition,"New").trim();
                 	if(cond == "")
                 	{
                 		cond = "New";
                 	}
                 	if(cond == "New")
                 	{
                 		item_rec.Stock_On_Hand_New=ifnull(item_rec.Stock_On_Hand_New,0.0) + qty_change;
                 	}
                 	else if(cond == "Used")
                 	{
                 		item_rec.Stock_On_Hand_Used=ifnull(item_rec.Stock_On_Hand_Used,0.0) + qty_change;
                 	}
                 }

map stock.apply_average_cost_on_receive(int item_id, float in_qty_base, float in_unit_cost_base)
{
                 	result = Map();
                 	result.put("ok",false);
                 	result.put("new_avg",0.0);
                 	result.put("message","");
                 	// Guards
                 	if(item_id == null || in_qty_base == null || in_qty_base <= 0 || in_unit_cost_base == null || in_unit_cost_base < 0)
                 	{
                 		result.put("message","Invalid inputs for avg cost calculation.");
                 		return result;
                 	}
                 	item_rec = Items_Register[ID == item_id];
                 	if(item_rec.ID == null)
                 	{
                 		result.put("message","Item not found.");
                 		return result;
                 	}
                 	// =====================================================
                 	// IMPORTANT FIX:
                 	// This function is now called AFTER Stock IN is posted.
                 	// So current Stock_On_Hand already includes in_qty_base.
                 	// We compute stock BEFORE receipt by subtracting in_qty_base.
                 	// =====================================================
                 	old_qty = ifnull(item_rec.Stock_On_Hand,0.0) - in_qty_base;
                 	if(old_qty < 0)
                 	{
                 		old_qty = 0.0;
                 	}
                 	old_avg = ifnull(item_rec.Average_Cost,0.0);
                 	// Weighted average
                 	new_avg = 0.0;
                 	if(old_qty <= 0)
                 	{
                 		new_avg = in_unit_cost_base;
                 	}
                 	else
                 	{
                 		new_avg = (old_qty * old_avg + in_qty_base * in_unit_cost_base) / (old_qty + in_qty_base);
                 	}
                 	// Save Average Cost
                 	item_rec.Average_Cost=new_avg;
                 	// =====================================================
                 	// Stock Value update (requires Items.Stock_Value field)
                 	// Stock Value = current stock * average cost
                 	// =====================================================
                 	current_qty = ifnull(item_rec.Stock_On_Hand,0.0);
                 	if(current_qty > 0)
                 	{
                 		item_rec.Stock_Value=current_qty * new_avg;
                 	}
                 	else
                 	{
                 		item_rec.Stock_Value=0.0;
                 	}
                 	result.put("ok",true);
                 	result.put("new_avg",new_avg);
                 	return result;
                 }

void stock.apply_ledger_delta(int item_id, int store_id, float qty_delta, string stock_condition)
{
                 	if(item_id == null || store_id == null || qty_delta == null)
                 	{
                 		return;
                 	}
                 	cond = ifnull(stock_condition,"New").trim();
                 	if(cond == "")
                 	{
                 		cond = "New";
                 	}
                 	led_id = thisapp.get_or_create_store_item_stock(item_id,store_id,cond);
                 	if(led_id == null)
                 	{
                 		return;
                 	}
                 	led = Store_Item_Stock[ID == led_id];
                 	if(led.ID == null)
                 	{
                 		return;
                 	}
                 	current_qty = ifnull(led.Qty_On_Hand,0.0);
                 	new_qty = current_qty + qty_delta;
                 	// Update ledger qty + timestamp
                 	led.Qty_On_Hand=new_qty;
                 	led.Last_Updated=zoho.currenttime;
                 	// ----------------------------
                 	// Cleanup: delete ledger rows that are effectively zero
                 	// ----------------------------
                 	// Float tolerance to avoid leftovers like 0.0000001
                 	if(ifnull(led.Qty_On_Hand,0.0) <= 0.000001)
                 	{
                 		delete from Store_Item_Stock[ID == led.ID];
                 	}
                 }

void stock.backfill_store_costs_replay()
{
                 	// =========================================================
                 	// ONE-TIME BACKFILL: REBUILD STORE COSTS BY REPLAYING TXNS
                 	// =========================================================
                 	// PURPOSE
                 	// - Rebuild Default_Cost, Average_Cost, Stock_Value on
                 	//   Store_Item_Stock by replaying Stock_Transactions
                 	// - More accurate than using only latest transaction
                 	//
                 	// ASSUMPTION
                 	// Store_Item_Stock has these added fields:
                 	// - Default_Cost   (Currency)
                 	// - Average_Cost   (Currency)
                 	// - Stock_Value    (Currency)
                 	//
                 	// OPTIONAL MODE
                 	// force_rebuild = true  -> rebuild every row
                 	// force_rebuild = false -> rebuild only missing/blank rows
                 	// =========================================================
                 	force_rebuild = true;
                 	updated_count = 0;
                 	skipped_count = 0;
                 	no_txn_count = 0;
                 	for each  led in Store_Item_Stock[ID != 0]
                 	{
                 		needs_update = force_rebuild;
                 		if(!needs_update)
                 		{
                 			if(ifnull(led.Default_Cost,0.0) <= 0 || ifnull(led.Average_Cost,0.0) <= 0 || (ifnull(led.Qty_On_Hand,0.0) > 0 && ifnull(led.Stock_Value,0.0) <= 0))
                 			{
                 				needs_update = true;
                 			}
                 		}
                 		if(!needs_update)
                 		{
                 			skipped_count = skipped_count + 1;
                 			continue;
                 		}
                 		item_id = led.Item;
                 		store_id = led.Store;
                 		cond = ifnull(led.Stock_Condition,"New").trim();
                 		if(cond == "")
                 		{
                 			cond = "New";
                 		}
                 		if(item_id == null || store_id == null)
                 		{
                 			skipped_count = skipped_count + 1;
                 			continue;
                 		}
                 		// -----------------------------------------------------
                 		// Pull all matching transactions
                 		// -----------------------------------------------------
                 		trans_list = Stock_Transactions[Item == item_id && Store == store_id && Stock_Condition == cond];
                 		if(trans_list.count() == 0)
                 		{
                 			// no transactions for this ledger row
                 			if(ifnull(led.Qty_On_Hand,0.0) <= 0)
                 			{
                 				led.Default_Cost=0.0;
                 				led.Average_Cost=0.0;
                 				led.Stock_Value=0.0;
                 				led.Last_Updated=zoho.currenttime;
                 				updated_count = updated_count + 1;
                 			}
                 			else
                 			{
                 				no_txn_count = no_txn_count + 1;
                 			}
                 			continue;
                 		}
                 		// -----------------------------------------------------
                 		// Build sortable list by transaction order
                 		// Prefer Created_Time, fallback to ID
                 		// -----------------------------------------------------
                 		sort_map = Map();
                 		key_list = List();
                 		for each  t in trans_list
                 		{
                 			sort_key = "";
                 			if(t.Created_Time != null)
                 			{
                 				// include ID to avoid duplicate keys
                 				sort_key = t.Created_Time.toString("yyyyMMddHHmmss") + "_" + t.ID.toString();
                 			}
                 			else
                 			{
                 				sort_key = "99999999999999_" + t.ID.toString();
                 			}
                 			sort_map.put(sort_key,t.ID);
                 			key_list.add(sort_key);
                 		}
                 		key_list.sort(true);
                 		// -----------------------------------------------------
                 		// Replay transactions
                 		// -----------------------------------------------------
                 		run_qty = 0.0;
                 		run_avg = 0.0;
                 		last_in_cost = 0.0;
                 		for each  k in key_list
                 		{
                 			tx_id = sort_map.get(k);
                 			tx = Stock_Transactions[ID == tx_id];
                 			if(tx.ID == null)
                 			{
                 				continue;
                 			}
                 			tx_qty = ifnull(tx.Quantity,0.0);
                 			if(tx_qty <= 0)
                 			{
                 				continue;
                 			}
                 			tx_type = ifnull(tx.Transaction_Type,"").trim();
                 			tx_cost = ifnull(tx.Unit_Cost_Base,0.0);
                 			if(tx_type == "Stock In")
                 			{
                 				// Weighted average on receipt only when cost > 0
                 				if(tx_cost > 0)
                 				{
                 					if(run_qty <= 0)
                 					{
                 						run_avg = tx_cost;
                 					}
                 					else
                 					{
                 						run_avg = (run_qty * run_avg + tx_qty * tx_cost) / (run_qty + tx_qty);
                 					}
                 					last_in_cost = tx_cost;
                 				}
                 				run_qty = run_qty + tx_qty;
                 			}
                 			else if(tx_type == "Stock Out")
                 			{
                 				// Stock out reduces qty, average cost remains same
                 				run_qty = run_qty - tx_qty;
                 				if(run_qty < 0)
                 				{
                 					run_qty = 0.0;
                 				}
                 			}
                 		}
                 		// -----------------------------------------------------
                 		// Save rebuilt costs to ledger
                 		// -----------------------------------------------------
                 		if(last_in_cost > 0)
                 		{
                 			led.Default_Cost=last_in_cost;
                 		}
                 		else
                 		{
                 			led.Default_Cost=0.0;
                 		}
                 		if(run_avg > 0)
                 		{
                 			led.Average_Cost=run_avg;
                 		}
                 		else
                 		{
                 			led.Average_Cost=ifnull(led.Default_Cost,0.0);
                 		}
                 		// Use actual current ledger qty for stock value
                 		current_qty = ifnull(led.Qty_On_Hand,0.0);
                 		value_cost = ifnull(led.Average_Cost,0.0);
                 		if(value_cost <= 0)
                 		{
                 			value_cost = ifnull(led.Default_Cost,0.0);
                 		}
                 		if(current_qty > 0 && value_cost > 0)
                 		{
                 			led.Stock_Value=current_qty * value_cost;
                 		}
                 		else
                 		{
                 			led.Stock_Value=0.0;
                 		}
                 		led.Last_Updated=zoho.currenttime;
                 		updated_count = updated_count + 1;
                 	}
                 	info "Replay backfill complete.";
                 	info "Updated rows: " + updated_count.toString();
                 	info "Skipped rows: " + skipped_count.toString();
                 	info "Rows with stock but no transactions: " + no_txn_count.toString();
                 }

map stock.get_stock_summary(int item_id, int store_id, string stock_condition)
{
                 	stock_map = Map();
                 	stock_map.put("global_stock",0.0);
                 	stock_map.put("store_stock",0.0);
                 	stock_map.put("cost",0.0);
                 	if(item_id == null)
                 	{
                 		return stock_map;
                 	}
                 	cond = ifnull(stock_condition,"").trim();
                 	if(cond == "")
                 	{
                 		cond = "New";
                 	}
                 	// Global item stock + fallback cost
                 	item_rec = Items_Register[ID == item_id];
                 	if(item_rec.ID != null)
                 	{
                 		stock_map.put("global_stock",ifnull(item_rec.Stock_On_Hand,0.0));
                 		stock_map.put("cost",ifnull(item_rec.Default_Cost,0.0));
                 	}
                 	// Store stock + preferred cost
                 	if(store_id != null)
                 	{
                 		led = Store_Item_Stock[Item.ID == item_id && Store.ID == store_id && Stock_Condition == cond];
                 		if(led.ID != null)
                 		{
                 			stock_map.put("store_stock",ifnull(led.Qty_On_Hand,0.0));
                 			if(led.Default_Cost != null && led.Default_Cost > 0)
                 			{
                 				stock_map.put("cost",ifnull(led.Default_Cost,0.0));
                 			}
                 		}
                 	}
                 	return stock_map;
                 }

map stock.issue_stock_from_CleanSand(int item_id, int store_id, float qty, int uom_id, string stock_condition, float line_total, string ref_no, int source_record_id)
{
                 	result = Map();
                 	result.put("ok",false);
                 	result.put("message","");
                 	result.put("base_qty",0.0);
                 	result.put("store_stock_before",0.0);
                 	result.put("global_stock_before",0.0);
                 	result.put("store_stock",0.0);
                 	result.put("global_stock",0.0);
                 	result.put("transaction_id",null);
                 	// =====================================================
                 	// VALIDATION
                 	// =====================================================
                 	if(item_id == null || store_id == null || qty == null || qty <= 0 || uom_id == null || source_record_id == null)
                 	{
                 		result.put("message","Missing required stock issue values.");
                 		return result;
                 	}
                 	// =====================================================
                 	// STOCK CONDITION
                 	// =====================================================
                 	cond = ifnull(stock_condition,"New").trim();
                 	if(cond == "")
                 	{
                 		cond = "New";
                 	}
                 	if(cond != "New" && cond != "Used")
                 	{
                 		result.put("message","Invalid stock condition: " + cond);
                 		return result;
                 	}
                 	// =====================================================
                 	// UOM CONVERSION
                 	// =====================================================
                 	check = thisapp.uom.ensure_uom_conversion(item_id,uom_id);
                 	if(check == null || check.get("ok") != true)
                 	{
                 		conversion_message = "UOM conversion failed.";
                 		if(check != null)
                 		{
                 			conversion_message = ifnull(check.get("message"),conversion_message);
                 		}
                 		result.put("message",conversion_message);
                 		return result;
                 	}
                 	base_qty = thisapp.uom.convert_to_base_qty(item_id,uom_id,qty);
                 	if(base_qty == null || base_qty <= 0)
                 	{
                 		result.put("message","Invalid base quantity.");
                 		return result;
                 	}
                 	result.put("base_qty",base_qty);
                 	// =====================================================
                 	// BALANCE BEFORE RECONCILIATION
                 	// =====================================================
                 	stock_before_map = thisapp.stock.get_stock_summary(item_id,store_id,cond);
                 	store_stock_before = ifnull(stock_before_map.get("store_stock"),0.0);
                 	global_stock_before = ifnull(stock_before_map.get("global_stock"),0.0);
                 	result.put("store_stock_before",store_stock_before);
                 	result.put("global_stock_before",global_stock_before);
                 	source_form_text = "Clean Sand Management - Item Issuing Details";
                 	// =====================================================
                 	// FIND EXISTING REVERSIBLE QUANTITY
                 	// =====================================================
                 	old_txns = Stock_Transactions[Source_Record_ID == source_record_id && Source_Form == source_form_text && Transaction_Type == "Stock Out"];
                 	reversible_qty = 0.0;
                 	for each  old_txn in old_txns
                 	{
                 		old_condition = ifnull(old_txn.Stock_Condition,"New").trim();
                 		if(old_condition == "")
                 		{
                 			old_condition = "New";
                 		}
                 		old_store_id = old_txn.Store;
                 		old_qty = ifnull(old_txn.Quantity,0.0);
                 		if(old_txn.Item == item_id && old_store_id == store_id && old_condition == cond && old_qty > 0)
                 		{
                 			reversible_qty = reversible_qty + old_qty;
                 		}
                 	}
                 	available_after_reverse = store_stock_before + reversible_qty;
                 	if(base_qty > available_after_reverse)
                 	{
                 		result.put("message","Insufficient store stock. Available after reversing old issue: " + available_after_reverse + ", Required: " + base_qty);
                 		return result;
                 	}
                 	// =====================================================
                 	// RECONCILE STOCK OUT
                 	// =====================================================
                 	thisapp.stock.reconcile_stock_out_on_edit(source_record_id,source_form_text,item_id,store_id,base_qty,cond,ifnull(line_total,0.0),"Item Issuing Voucher",ifnull(ref_no,""));
                 	// =====================================================
                 	// VERIFY RESULTING TRANSACTION
                 	// =====================================================
                 	posted_txns = Stock_Transactions[Source_Record_ID == source_record_id && Source_Form == source_form_text && Transaction_Type == "Stock Out"];
                 	posted_count = 0;
                 	posted_total_qty = 0.0;
                 	posted_transaction_id = null;
                 	posted_item_id = null;
                 	posted_store_id = null;
                 	posted_condition = "";
                 	for each  posted_txn in posted_txns
                 	{
                 		posted_count = posted_count + 1;
                 		posted_qty = ifnull(posted_txn.Quantity,0.0);
                 		if(posted_qty > 0)
                 		{
                 			posted_total_qty = posted_total_qty + posted_qty;
                 		}
                 		if(posted_count == 1)
                 		{
                 			posted_transaction_id = posted_txn.ID;
                 			posted_item_id = posted_txn.Item;
                 			posted_store_id = posted_txn.Store;
                 			posted_condition = ifnull(posted_txn.Stock_Condition,"New").trim();
                 			if(posted_condition == "")
                 			{
                 				posted_condition = "New";
                 			}
                 		}
                 	}
                 	qty_difference = posted_total_qty - base_qty;
                 	if(qty_difference < 0)
                 	{
                 		qty_difference = qty_difference * -1;
                 	}
                 	if(posted_count != 1 || qty_difference > 0.000001 || posted_item_id != item_id || posted_store_id != store_id || posted_condition != cond)
                 	{
                 		result.put("message","Stock reconciliation could not be verified.");
                 		result.put("posted_count",posted_count);
                 		result.put("posted_quantity",posted_total_qty);
                 		return result;
                 	}
                 	// =====================================================
                 	// FETCH UPDATED BALANCES
                 	// =====================================================
                 	stock_after_map = thisapp.stock.get_stock_summary(item_id,store_id,cond);
                 	store_stock_after = ifnull(stock_after_map.get("store_stock"),0.0);
                 	global_stock_after = ifnull(stock_after_map.get("global_stock"),0.0);
                 	result.put("store_stock",store_stock_after);
                 	result.put("global_stock",global_stock_after);
                 	result.put("transaction_id",posted_transaction_id);
                 	result.put("ok",true);
                 	result.put("message","Stock deducted and verified successfully from Clean Sand Management.");
                 	return result;
                 }

