                 	// =====================================================
                 	// VALIDATION
                 	// =====================================================
                 	if(item_id == null || store_id == null || qty == null || qty <= 0 || uom_id == null || source_record_id == null)
                 	{
                 		result.put("message","Missing required stock issue values.");
                 		return result;
                 	}
                 	cond = ifnull(stock_condition,"New").trim();
                 	if(cond == "")
                 	{
                 		cond = "New";
                 	}
                 	if(cond != "New" && cond != "Used")
                 	{
                 		result.put("message","Invalid stock condition: " + cond);
                 		return result;
                 	}
                 	// =====================================================
                 	// UOM CONVERSION
                 	// =====================================================
                 	check = thisapp.uom.ensure_uom_conversion(item_id,uom_id);
                 	if(check == null || check.get("ok") != true)
                 	{
                 		conversion_message = "UOM conversion failed.";
                 		if(check != null)
                 		{
                 			conversion_message = ifnull(check.get("message"),conversion_message);
                 		}
                 		result.put("message",conversion_message);
                 		return result;
                 	}
                 	base_qty = thisapp.uom.convert_to_base_qty(item_id,uom_id,qty);
                 	if(base_qty == null || base_qty <= 0)
                 	{
                 		result.put("message","Invalid base quantity.");
                 		return result;
                 	}
                 	result.put("base_qty",base_qty);
                 	// =====================================================
                 	// BALANCE BEFORE RECONCILIATION
                 	// =====================================================
                 	stock_before_map = thisapp.stock.get_stock_summary(item_id,store_id,cond);
                 	store_stock_before = ifnull(stock_before_map.get("store_stock"),0.0);
                 	global_stock_before = ifnull(stock_before_map.get("global_stock"),0.0);
                 	result.put("store_stock_before",store_stock_before);
                 	result.put("global_stock_before",global_stock_before);
                 	source_form_text = "Freedom City Kids Park Management - Item Issuing Details";
                 	// =====================================================
                 	// FIND REVERSIBLE OLD ISSUE
                 	// =====================================================
                 	old_txns = Stock_Transactions[Source_Record_ID == source_record_id && Source_Form == source_form_text && Transaction_Type == "Stock Out"];
                 	reversible_qty = 0.0;
                 	for each  old_txn in old_txns
                 	{
                 		old_condition = ifnull(old_txn.Stock_Condition,"New").trim();
                 		if(old_condition == "")
                 		{
                 			old_condition = "New";
                 		}
                 		old_qty = ifnull(old_txn.Quantity,0.0);
                 		if(old_txn.Item == item_id && old_txn.Store == store_id && old_condition == cond && old_qty > 0)
                 		{
                 			reversible_qty = reversible_qty + old_qty;
                 		}
                 	}
                 	available_after_reverse = store_stock_before + reversible_qty;
                 	if(base_qty > available_after_reverse)
                 	{
                 		result.put("message","Insufficient store stock. Available after reversing old issue: " + available_after_reverse + ", Required: " + base_qty);
                 		return result;
                 	}
                 	// =====================================================
                 	// RECONCILE STOCK OUT
                 	// =====================================================
                 	thisapp.stock.reconcile_stock_out_on_edit(source_record_id,source_form_text,item_id,store_id,base_qty,cond,ifnull(line_total,0.0),"Item Issuing Voucher",ifnull(ref_no,""));
                 	// =====================================================
                 	// VERIFY POSTED TRANSACTION
                 	// =====================================================
                 	posted_txns = Stock_Transactions[Source_Record_ID == source_record_id && Source_Form == source_form_text && Transaction_Type == "Stock Out"];
                 	posted_count = 0;
                 	posted_total_qty = 0.0;
                 	posted_transaction_id = null;
                 	posted_item_id = null;
                 	posted_store_id = null;
                 	posted_condition = "";
                 	for each  posted_txn in posted_txns
                 	{
                 		posted_count = posted_count + 1;
                 		posted_qty = ifnull(posted_txn.Quantity,0.0);
                 		if(posted_qty > 0)
                 		{
                 			posted_total_qty = posted_total_qty + posted_qty;
                 		}
                 		if(posted_count == 1)
                 		{
                 			posted_transaction_id = posted_txn.ID;
                 			posted_item_id = posted_txn.Item;
                 			posted_store_id = posted_txn.Store;
                 			posted_condition = ifnull(posted_txn.Stock_Condition,"New").trim();
                 			if(posted_condition == "")
                 			{
                 				posted_condition = "New";
                 			}
                 		}
                 	}
                 	qty_difference = posted_total_qty - base_qty;
                 	if(qty_difference < 0)
                 	{
                 		qty_difference = qty_difference * -1;
                 	}
                 	if(posted_count != 1 || qty_difference > 0.000001 || posted_item_id != item_id || posted_store_id != store_id || posted_condition != cond)
                 	{
                 		result.put("message","Stock reconciliation could not be verified.");
                 		result.put("posted_count",posted_count);
                 		result.put("posted_quantity",posted_total_qty);
                 		return result;
                 	}
                 	// =====================================================
                 	// BALANCE AFTER RECONCILIATION
                 	// =====================================================
                 	stock_after_map = thisapp.stock.get_stock_summary(item_id,store_id,cond);
                 	store_stock_after = ifnull(stock_after_map.get("store_stock"),0.0);
                 	global_stock_after = ifnull(stock_after_map.get("global_stock"),0.0);
                 	result.put("store_stock",store_stock_after);
                 	result.put("global_stock",global_stock_after);
                 	result.put("transaction_id",posted_transaction_id);
                 	result.put("ok",true);
                 	result.put("message","Stock deducted and verified successfully from Freedom City Kids Park Management.");
                 	return result;
                 }

