                 	// =====================================================
                 	thisapp.stock.reconcile_stock_out_on_edit(source_record_id,source_form_text,item_id,store_id,base_qty,cond,ifnull(line_total,0.0),"Item Issuing Voucher",ifnull(ref_no,""));
                 	// =====================================================
                 	// VERIFY RECONCILIATION
                 	// =====================================================
                 	posted_count = 0;
                 	posted_total_qty = 0.0;
                 	posted_transaction_id = null;
                 	posted_item_id = null;
                 	posted_store_id = null;
                 	posted_condition = "";
                 	posted_txns = Stock_Transactions[Source_Record_ID == source_record_id && Source_Form == source_form_text && Transaction_Type == "Stock Out"];
                 	for each  posted_txn in posted_txns
                 	{
                 		posted_count = posted_count + 1;
                 		posted_qty = ifnull(posted_txn.Quantity,0.0);
                 		if(posted_qty > 0)
                 		{
                 			posted_total_qty = posted_total_qty + posted_qty;
                 		}
                 		if(posted_count == 1)
                 		{
                 			posted_transaction_id = posted_txn.ID;
                 			posted_item_id = posted_txn.Item;
                 			posted_store_id = posted_txn.Store;
                 			posted_condition = ifnull(posted_txn.Stock_Condition,"New").trim();
                 			if(posted_condition == "")
                 			{
                 				posted_condition = "New";
                 			}
                 		}
                 	}
                 	qty_difference = posted_total_qty - base_qty;
                 	if(qty_difference < 0)
                 	{
                 		qty_difference = qty_difference * -1;
                 	}
                 	if(posted_count != 1 || qty_difference > 0.000001 || posted_item_id != item_id || posted_store_id != store_id || posted_condition != cond)
                 	{
                 		result.put("message","Stock reconciliation could not be verified.");
                 		result.put("posted_count",posted_count);
                 		result.put("posted_quantity",posted_total_qty);
                 		return result;
                 	}
                 	// =====================================================
                 	// GET UPDATED BALANCES AFTER RECONCILIATION
                 	// =====================================================
                 	stock_after_map = thisapp.stock.get_stock_summary(item_id,store_id,cond);
                 	store_stock_after = ifnull(stock_after_map.get("store_stock"),0.0);
                 	global_stock_after = ifnull(stock_after_map.get("global_stock"),0.0);
                 	result.put("store_stock",store_stock_after);
                 	result.put("global_stock",global_stock_after);
                 	result.put("transaction_id",posted_transaction_id);
                 	result.put("ok",true);
                 	result.put("message","Stock deducted and transaction verified successfully.");
                 	return result;
                 }

void stock.log_stock_transaction(int item_id, float qty_base, string transaction_type, string reference_type, string reference_number, int store_id, string display_name_store, string stock_condition, float unit_cost_base, string source_form, int source_record_id)
{
                 	// =====================================================
                 	// 1) REQUIRED VALUES
                 	// =====================================================
                 	if(item_id == null)
                 	{
                 		info "Stock transaction stopped: Item ID is empty.";
                 		return;
                 	}
                 	if(store_id == null)
                 	{
                 		info "Stock transaction stopped: Store ID is empty.";
                 		return;
                 	}
                 	if(qty_base == null || qty_base <= 0)
                 	{
                 		info "Stock transaction stopped: Quantity must be greater than zero.";
                 		return;
                 	}
                 	item_rec = Items_Register[ID == item_id];
                 	if(item_rec.ID == null)
                 	{
                 		info "Stock transaction stopped: Item record was not found.";
                 		return;
                 	}
                 	// =====================================================
                 	// 2) STOCK CONDITION
                 	// Allows New, Used, In Service and other configured values.
                 	// =====================================================
                 	cond = ifnull(stock_condition,"New").trim();
                 	if(cond == "")
                 	{
                 		cond = "New";
                 	}
                 	// =====================================================
                 	// 3) TRANSACTION TYPE
                 	// =====================================================
                 	tx_type = ifnull(transaction_type,"").trim();
                 	if(tx_type == "")
                 	{
                 		info "Stock transaction stopped: Transaction type is empty.";
                 		return;
                 	}
                 	valid_transaction = false;
                 	if(tx_type == "Stock In")
                 	{
                 		valid_transaction = true;
                 	}
                 	else if(tx_type == "Stock Out")
                 	{
                 		valid_transaction = true;
                 	}
                 	else if(tx_type == "Adjustment Increase")
                 	{
                 		valid_transaction = true;
                 	}
                 	else if(tx_type == "Adjustment Decrease")
                 	{
                 		valid_transaction = true;
                 	}
                 	else if(tx_type == "Opening Stock")
                 	{
                 		valid_transaction = true;
                 	}
                 	if(valid_transaction == false)
                 	{
                 		info "Stock transaction stopped: Invalid transaction type: " + tx_type;
                 		return;
                 	}
                 	// =====================================================
                 	// 4) REFERENCES
                 	// =====================================================
                 	ref_type = ifnull(reference_type,"").trim();
                 	src_form = ifnull(source_form,"").trim();
                 	src_id = source_record_id;
                 	ref_no = ifnull(reference_number,"").toString().trim();
                 	if(unit_cost_base == null || unit_cost_base < 0)
                 	{
                 		unit_cost_base = 0.0;
                 	}
                 	// =====================================================
                 	// 5) PREVENT DUPLICATE TRANSACTIONS
                 	// =====================================================
                 	if(src_id != null && src_form != "")
                 	{
                 		existing_txn = Stock_Transactions[Item == item_id && Store == store_id && Stock_Condition == cond && Transaction_Type == tx_type && Source_Form == src_form && Source_Record_ID == src_id];
                 		if(existing_txn.ID != null)
                 		{
                 			info "Stock transaction skipped: Matching transaction already exists.";
                 			info "Transaction ID: " + existing_txn.ID;
                 			return;
                 		}
                 	}
                 	// =====================================================
                 	// 6) OPENING STOCK REFERENCE
                 	// =====================================================
                 	if(src_id != null && src_form == "Opening_Stock_Details" || src_form == "Opening Stock Details")
                 	{
                 		osd_ref = Opening_Stock_Details[ID == src_id];
                 		if(osd_ref.ID != null)
                 		{
                 			opening_ref = ifnull(osd_ref.Display_Name_Opening_Stock_Voucher,"").trim();
                 			if(opening_ref != "")
                 			{
                 				ref_no = opening_ref;
                 			}
                 			else if(osd_ref.Opening_Stock_Voucher != null)
                 			{
                 				osv_ref = Opening_Stock_Voucher[ID == osd_ref.Opening_Stock_Voucher];
                 				if(osv_ref.ID != null)
                 				{
                 					ref_no = ifnull(osv_ref.Display_Name_Opening_Stock_Voucher,ref_no).trim();
                 				}
                 			}
                 		}
                 	}
                 	// =====================================================
                 	// 7) ITEM ISSUING REFERENCE
                 	// =====================================================
                 	else if(src_id != null && src_form == "Item Issuing Details" || src_form == "Item_Issuing_Details")
                 	{
                 		iid_ref = Item_Issuing_Details[ID == src_id];
                 		if(iid_ref.ID != null)
                 		{
                 			issuing_ref = ifnull(iid_ref.Item_Issuing_Number,"").toString().trim();
                 			if(issuing_ref != "")
                 			{
                 				ref_no = issuing_ref;
                 			}
                 		}
                 	}
                 	// =====================================================
                 	// 8) STOCK-TAKING REFERENCE
                 	// =====================================================
                 	else if(src_id != null && src_form == "Stock Taking Details" || src_form == "Stock_Taking_Details")
                 	{
                 		std_ref = Stock_Taking_Details[ID == src_id];
                 		if(std_ref.ID != null)
                 		{
                 			stock_take_ref = ifnull(std_ref.Stock_Taking_Voucher_Number,"").toString().trim();
                 			if(stock_take_ref != "")
                 			{
                 				ref_no = stock_take_ref;
                 			}
                 		}
                 	}
                 	if(ref_no == "" && src_id != null)
                 	{
                 		ref_no = src_id.toString();
                 	}
                 	// =====================================================
                 	// 9) ITEM DISPLAY NAME
                 	// =====================================================
                 	display_item = ifnull(item_rec.Item_Name,"").trim();
                 	item_sku = ifnull(item_rec.SKU,"").trim();
                 	if(item_sku != "")
                 	{
                 		if(display_item != "")
                 		{
                 			display_item = display_item + " - " + item_sku;
                 		}
                 		else
                 		{
                 			display_item = item_sku;
                 		}
                 	}
                 	// =====================================================
                 	// 10) STORE DISPLAY NAME
                 	// =====================================================
                 	display_store = ifnull(display_name_store,"").trim();
                 	if(display_store == "")
                 	{
                 		store_led = Store_Item_Stock[Item == item_id && Store == store_id && Stock_Condition == cond];
                 		if(store_led.ID != null)
                 		{
                 			display_store = ifnull(store_led.Display_Name_Store,"").trim();
                 		}
                 	}
                 	// Stock Receiving source
                 	if(display_store == "" && src_id != null && src_form == "Stock Receiving Details" || src_form == "Stock_Receiving_Details")
                 	{
                 		srd = Stock_Receiving_Details[ID == src_id];
                 		if(srd.ID != null && srd.Stock_Receiving_Voucher != null)
                 		{
                 			srv = Stock_Receiving_Voucher[ID == srd.Stock_Receiving_Voucher];
                 			if(srv.ID != null)
                 			{
                 				display_store = ifnull(srv.Display_Name_Store,"").trim();
                 			}
                 		}
                 	}
                 	// Opening Stock source
                 	if(display_store == "" && src_id != null && src_form == "Opening_Stock_Details" || src_form == "Opening Stock Details")
                 	{
                 		osd = Opening_Stock_Details[ID == src_id];
                 		if(osd.ID != null && osd.Opening_Stock_Voucher != null)
                 		{
                 			osv = Opening_Stock_Voucher[ID == osd.Opening_Stock_Voucher];
                 			if(osv.ID != null)
                 			{
                 				display_store = ifnull(osv.Display_Name_Store,"").trim();
                 			}
                 		}
                 	}
                 	// Item Issuing source
                 	if(display_store == "" && src_id != null && src_form == "Item Issuing Details" || src_form == "Item_Issuing_Details")
                 	{
                 		iid = Item_Issuing_Details[ID == src_id];
                 		if(iid.ID != null && iid.Issuing_Voucher != null)
                 		{
                 			iiv = Item_Issuing_Voucher[ID == iid.Issuing_Voucher];
                 			if(iiv.ID != null)
                 			{
                 				display_store = ifnull(iiv.Display_Name_Store,"").trim();
                 			}
                 		}
                 	}
                 	// Stock Taking source
                 	if(display_store == "" && src_id != null && src_form == "Stock Taking Details" || src_form == "Stock_Taking_Details")
                 	{
                 		std_store = Stock_Taking_Details[ID == src_id];
                 		if(std_store.ID != null)
                 		{
                 			display_store = ifnull(std_store.Store,"").toString().trim();
                 		}
                 	}
                 	// =====================================================
                 	// 11) BASE UNIT OF MEASURE
                 	// =====================================================
                 	base_uom_name = "";
                 	if(item_rec.Base_Unit_Of_Measure != null)
                 	{
                 		uom_rec = Unit_Of_Measure[ID == item_rec.Base_Unit_Of_Measure];
                 		if(uom_rec.ID != null)
                 		{
                 			base_uom_name = ifnull(uom_rec.Unit_Of_Measure_Name,"").trim();
                 		}
                 	}
                 	// =====================================================
                 	// 12) TRANSACTION DELTA
                 	// =====================================================
                 	qty_delta = 0.0;
                 	if(tx_type == "Stock In" || tx_type == "Adjustment Increase" || tx_type == "Opening Stock")
                 	{
                 		qty_delta = qty_base;
                 	}
                 	else if(tx_type == "Stock Out" || tx_type == "Adjustment Decrease")
                 	{
                 		qty_delta = -1 * qty_base;
                 	}
                 	// =====================================================
                 	// 13) CURRENT STORE BALANCE
                 	// =====================================================
                 	store_before = 0.0;
                 	store_average_before = 0.0;
                 	store_default_cost = 0.0;
                 	led_before = Store_Item_Stock[Item == item_id && Store == store_id && Stock_Condition == cond];
                 	if(led_before.ID != null)
                 	{
                 		store_before = ifnull(led_before.Qty_On_Hand,0.0);
                 		store_average_before = ifnull(led_before.Average_Cost,0.0);
                 		store_default_cost = ifnull(led_before.Default_Cost,0.0);
                 		if(display_store == "")
                 		{
                 			display_store = ifnull(led_before.Display_Name_Store,"").trim();
                 		}
                 	}
                 	// =====================================================
                 	// 14) STOCK-OUT VALIDATION
                 	// =====================================================
                 	if(tx_type == "Stock Out" || tx_type == "Adjustment Decrease" && store_before < qty_base)
                 	{
                 		info "Stock transaction stopped: Insufficient store stock.";
                 		info "Store: " + display_store;
                 		info "Condition: " + cond;
                 		info "Available: " + store_before;
                 		info "Required: " + qty_base;
                 		return;
                 	}
                 	store_after = store_before + qty_delta;
                 	if(store_after < -0.000001)
                 	{
                 		info "Stock transaction stopped: Store balance would become negative.";
                 		info "Available: " + store_before;
                 		info "Required: " + qty_base;
                 		return;
                 	}
                 	if(store_after >= -0.000001 && store_after <= 0.000001)
                 	{
                 		store_after = 0.0;
                 	}
                 	// =====================================================
                 	// 15) CURRENT GLOBAL ITEM BALANCE
                 	// =====================================================
                 	stock_before_total = ifnull(item_rec.Stock_On_Hand,0.0);
                 	stock_after_total = stock_before_total + qty_delta;
                 	if(stock_after_total < -0.000001)
                 	{
                 		info "Stock transaction stopped: Total item balance would become negative.";
                 		info "Available item stock: " + stock_before_total;
                 		info "Required: " + qty_base;
                 		return;
                 	}
                 	if(stock_after_total >= -0.000001 && stock_after_total <= 0.000001)
                 	{
                 		stock_after_total = 0.0;
                 	}
                 	// =====================================================
                 	// 16) TRANSACTION COST
                 	// =====================================================
                 	cost_for_transaction = unit_cost_base;
                 	if(tx_type == "Stock Out" || tx_type == "Adjustment Decrease")
                 	{
                 		if(store_average_before > 0)
                 		{
                 			cost_for_transaction = store_average_before;
                 		}
                 		else if(store_default_cost > 0)
                 		{
                 			cost_for_transaction = store_default_cost;
                 		}
                 		else if(ifnull(item_rec.Average_Cost,0.0) > 0)
                 		{
                 			cost_for_transaction = item_rec.Average_Cost;
                 		}
                 		else
                 		{
                 			cost_for_transaction = ifnull(item_rec.Default_Cost,0.0);
                 		}
                 	}
                 	if(cost_for_transaction < 0)
                 	{
                 		cost_for_transaction = 0.0;
                 	}
                 	line_amount = round(qty_base * cost_for_transaction,2);
                 	// =====================================================
                 	// 17) STORE AVERAGE COST
                 	// =====================================================
                 	store_avg_after = store_average_before;
                 	if(tx_type == "Stock In" || tx_type == "Adjustment Increase" || tx_type == "Opening Stock" && cond == "New" && unit_cost_base > 0)
                 	{
                 		if(store_before <= 0)
                 		{
                 			store_avg_after = unit_cost_base;
                 		}
                 		else
                 		{
                 			store_avg_after = (store_before * store_average_before + qty_base * unit_cost_base) / (store_before + qty_base);
                 		}
                 	}
                 	if(store_avg_after < 0)
                 	{
                 		store_avg_after = 0.0;
                 	}
                 	// =====================================================
                 	// 18) GLOBAL AVERAGE COST
                 	// =====================================================
                 	global_avg_before = ifnull(item_rec.Average_Cost,ifnull(item_rec.Default_Cost,0.0));
                 	global_avg_after = global_avg_before;
                 	if(tx_type == "Stock In" || tx_type == "Adjustment Increase" || tx_type == "Opening Stock" && cond == "New" && unit_cost_base > 0)
                 	{
                 		if(stock_before_total <= 0)
                 		{
                 			global_avg_after = unit_cost_base;
                 		}
                 		else
                 		{
                 			global_avg_after = (stock_before_total * global_avg_before + qty_base * unit_cost_base) / (stock_before_total + qty_base);
                 		}
                 	}
                 	if(global_avg_after < 0)
                 	{
                 		global_avg_after = 0.0;
                 	}
                 	// =====================================================
                 	// 19) INSERT TRANSACTION
                 	// =====================================================
                 	new_transaction_id = insert into Stock_Transactions
                 	[
                 		Transaction_Date=zoho.currentdate
                 		Item=item_rec.ID
                 		Display_Name_Item=display_item
                 		Transaction_Type=tx_type
                 		Quantity=qty_base
                 		Base_Unit_Of_Measure=base_uom_name
                 		Stock_Before=stock_before_total
                 		Stock_After=stock_after_total
                 		Store=store_id
                 		Display_Name_Store=display_store
                 		Reference_Type=ref_type
                 		Reference_Number=ref_no
                 		Stock_Condition=cond
                 		Unit_Cost_Base=cost_for_transaction
                 		Line_Amount=line_amount
                 		Avg_Cost_After=global_avg_after
                 		Source_Form=src_form
                 		Source_Record_ID=src_id
                 		Created_By=zoho.loginuser
                 		Created_Time=zoho.currenttime
                 		Added_User=zoho.loginuser
                 	];
                 	if(new_transaction_id == null)
                 	{
                 		info "Stock transaction stopped: Transaction record was not inserted.";
                 		return;
                 	}
                 	// =====================================================
                 	// 20) UPDATE ITEM BALANCE
                 	// =====================================================
                 	item_rec.Stock_On_Hand=stock_after_total;
                 	if(item_rec.Stock_On_Hand_New == null)
                 	{
                 		item_rec.Stock_On_Hand_New=0.0;
                 	}
                 	if(item_rec.Stock_On_Hand_Used == null)
                 	{
                 		item_rec.Stock_On_Hand_Used=0.0;
                 	}
                 	if(cond == "New")
                 	{
                 		new_condition_after = ifnull(item_rec.Stock_On_Hand_New,0.0) + qty_delta;
                 		if(new_condition_after < -0.000001)
                 		{
                 			delete from Stock_Transactions[ID == new_transaction_id];
                 			info "Stock transaction stopped: New stock would become negative.";
                 			return;
                 		}
                 		if(new_condition_after >= -0.000001 && new_condition_after <= 0.000001)
                 		{
                 			new_condition_after = 0.0;
                 		}
                 		item_rec.Stock_On_Hand_New=new_condition_after;
                 	}
                 	else if(cond == "Used")
                 	{
                 		used_condition_after = ifnull(item_rec.Stock_On_Hand_Used,0.0) + qty_delta;
                 		if(used_condition_after < -0.000001)
                 		{
                 			delete from Stock_Transactions[ID == new_transaction_id];
                 			info "Stock transaction stopped: Used stock would become negative.";
                 			return;
                 		}
                 		if(used_condition_after >= -0.000001 && used_condition_after <= 0.000001)
                 		{
                 			used_condition_after = 0.0;
                 		}
                 		item_rec.Stock_On_Hand_Used=used_condition_after;
                 	}
                 	item_rec.Average_Cost=global_avg_after;
                 	if(stock_after_total > 0)
                 	{
                 		item_rec.Stock_Value=round(stock_after_total * global_avg_after,2);
                 	}
                 	else
                 	{
                 		item_rec.Stock_Value=0.0;
                 	}
                 	// =====================================================
                 	// 21) UPDATE STORE LEDGER
                 	// =====================================================
                 	thisapp.stock.apply_ledger_delta(item_id,store_id,qty_delta,cond);
                 	led_after = Store_Item_Stock[Item == item_id && Store == store_id && Stock_Condition == cond];
                 	if(led_after.ID != null)
                 	{
                 		led_after.Display_Name_Item=display_item;
                 		if(display_store != "")
                 		{
                 			led_after.Display_Name_Store=display_store;
                 		}
                 		if(cond == "New")
                 		{
                 			led_after.Average_Cost=store_avg_after;
                 			if(unit_cost_base > 0 && qty_delta > 0)
                 			{
                 				led_after.Default_Cost=unit_cost_base;
                 			}
                 			led_after.Stock_Value=round(ifnull(led_after.Qty_On_Hand,0.0) * store_avg_after,2);
                 		}
                 		else if(cond == "Used")
                 		{
                 			led_after.Stock_Value=0.0;
                 		}
                 		else
                 		{
                 			led_after.Stock_Value=round(ifnull(led_after.Qty_On_Hand,0.0) * store_average_before,2);
                 		}
                 		led_after.Last_Updated=zoho.currenttime;
                 	}
                 	info "Stock transaction completed successfully.";
                 	info "Transaction ID: " + new_transaction_id;
                 	info "Transaction Type: " + tx_type;
                 	info "Store ID: " + store_id;
                 	info "Stock Condition: " + cond;
                 	info "Quantity: " + qty_base;
                 	info "Store Before: " + store_before;
                 	info "Store After: " + store_after;
                 }

map stock.post_stock_in_with_cost(int item_id, float qty_received, int uom_id, float unit_cost, string reference_type, string reference_number, int store_id, string display_name_store, string stock_condition)
{
                 	result = Map();
                 	result.put("ok",false);
                 	result.put("message","");
                 	result.put("base_qty",0.0);
                 	result.put("unit_cost_base",0.0);
                 	result.put("new_avg_cost",0.0);
                 	// =====================================================
                 	// 1. VALIDATE REQUIRED VALUES
                 	// =====================================================
                 	if(item_id == null)
                 	{
                 		result.put("message","Item is required.");
                 		return result;
                 	}
                 	if(store_id == null)
                 	{
                 		result.put("message","Store is required.");
                 		return result;
                 	}
                 	if(qty_received == null || qty_received <= 0)
                 	{
                 		result.put("message","Quantity received must be greater than zero.");
                 		return result;
                 	}
                 	if(uom_id == null)
                 	{
                 		result.put("message","Unit of Measure is required.");
                 		return result;
                 	}
                 	if(unit_cost == null || unit_cost < 0)
                 	{
                 		result.put("message","Unit cost must be zero or greater.");
                 		return result;
                 	}
                 	if(reference_type == null || reference_type.trim() == "")
                 	{
                 		result.put("message","Reference Type is required.");
                 		return result;
                 	}
                 	if(reference_number == null || reference_number.trim() == "")
                 	{
                 		result.put("message","Reference Number is required.");
                 		return result;
                 	}
                 	// =====================================================
                 	// 2. NORMALIZE VALUES
                 	// =====================================================
                 	cond = ifnull(stock_condition,"New").trim();
                 	if(cond == "")
                 	{
                 		cond = "New";
                 	}
                 	display_store = ifnull(display_name_store,"").trim();
                 	ref_type = reference_type.trim();
                 	ref_number = reference_number.trim();
                 	// =====================================================
                 	// 3. FETCH ITEM
                 	// =====================================================
                 	item_rec = Items_Register[ID == item_id];
                 	if(item_rec.ID == null)
                 	{
                 		result.put("message","Item record not found.");
                 		return result;
                 	}
                 	base_uom = item_rec.Base_Unit_Of_Measure;
                 	if(base_uom == null)
                 	{
                 		result.put("message","Item has no Base Unit Of Measure.");
                 		return result;
                 	}
                 	// =====================================================
                 	// 4. STORE DISPLAY NAME FALLBACK
                 	// =====================================================
                 	if(display_store == "")
                 	{
                 		existing_ledger = Store_Item_Stock[Item == item_id && Store == store_id && Stock_Condition == cond];
                 		if(existing_ledger.ID != null)
                 		{
                 			display_store = ifnull(existing_ledger.Display_Name_Store,"").trim();
                 		}
                 	}
                 	// =====================================================
                 	// 5. CONVERT QUANTITY TO BASE QUANTITY
                 	// =====================================================
                 	base_qty = thisapp.uom.convert_to_base_qty(item_id,uom_id,qty_received);
                 	if(base_qty == null || base_qty <= 0)
                 	{
                 		result.put("message","Base quantity conversion failed.");
                 		return result;
                 	}
                 	result.put("base_qty",base_qty);
                 	// =====================================================
                 	// 6. CONVERT UNIT COST TO BASE UNIT COST
                 	// =====================================================
                 	unit_cost_base = unit_cost;
                 	if(uom_id != base_uom)
                 	{
                 		conv = thisapp.uom.ensure_uom_conversion(item_id,uom_id);
                 		if(conv.get("ok") != true)
                 		{
                 			result.put("message",conv.get("message"));
                 			return result;
                 		}
                 		factor = conv.get("conversion_factor");
                 		if(factor == null || factor <= 0)
                 		{
                 			result.put("message","Invalid conversion factor.");
                 			return result;
                 		}
                 		// 1 selected UOM = factor × base UOM
                 		// Cost per base unit = selected UOM cost ÷ factor
                 		unit_cost_base = unit_cost / factor;
                 	}
                 	if(unit_cost_base < 0)
                 	{
                 		unit_cost_base = 0.0;
                 	}
                 	result.put("unit_cost_base",unit_cost_base);
                 	// =====================================================
                 	// 7. CALCULATE MOVING WEIGHTED AVERAGE
                 	// =====================================================
                 	old_qty = ifnull(item_rec.Stock_On_Hand,0.0);
                 	old_avg = ifnull(item_rec.Average_Cost,ifnull(item_rec.Default_Cost,0.0));
                 	new_avg = old_avg;
                 	if(unit_cost_base > 0)
                 	{
                 		if(old_qty <= 0)
                 		{
                 			new_avg = unit_cost_base;
                 		}
                 		else
                 		{
                 			new_avg = (old_qty * old_avg + base_qty * unit_cost_base) / (old_qty + base_qty);
                 		}
                 	}
                 	if(new_avg < 0)
                 	{
                 		new_avg = 0.0;
                 	}
                 	result.put("new_avg_cost",new_avg);
                 	// =====================================================
                 	// 8. LOG STOCK TRANSACTION
                 	// =====================================================
                 	thisapp.stock.log_stock_transaction(item_id,base_qty,"Stock In",ref_type,ref_number,store_id,display_store,cond,unit_cost_base,"Stock_Receiving_Details",0);
                 	// =====================================================
                 	// 9. UPDATE ITEM AVERAGE COST
                 	// =====================================================
                 	item_rec.Average_Cost=new_avg;
                 	if(unit_cost_base > 0)
                 	{
                 		item_rec.Default_Cost=unit_cost_base;
                 	}
                 	// =====================================================
                 	// 10. UPDATE STORE ITEM STOCK DISPLAY AND COSTS
                 	// =====================================================
                 	ledger = Store_Item_Stock[Item == item_id && Store == store_id && Stock_Condition == cond];
                 	if(ledger.ID != null)
                 	{
                 		display_item = ifnull(item_rec.Item_Name,"").trim();
                 		item_sku = ifnull(item_rec.SKU,"").trim();
                 		if(item_sku != "")
                 		{
                 			if(display_item != "")
                 			{
                 				display_item = display_item + " - " + item_sku;
                 			}
                 			else
                 			{
                 				display_item = item_sku;
                 			}
                 		}
                 		ledger.Display_Name_Item=display_item;
                 		ledger.Display_Name_Store=display_store;
                 		if(cond == "New")
                 		{
                 			ledger.Average_Cost=new_avg;
                 			if(unit_cost_base > 0)
                 			{
                 				ledger.Default_Cost=unit_cost_base;
                 			}
                 			ledger.Stock_Value=(ifnull(ledger.Qty_On_Hand,0.0) * new_avg).round(2);
                 		}
                 		else if(cond == "Used")
                 		{
                 			ledger.Stock_Value=0.0;
                 		}
                 		ledger.Last_Updated=zoho.currenttime;
                 	}
                 	// =====================================================
                 	// 11. UPDATE STOCK TRANSACTION COST FIELDS
                 	// =====================================================
                 	try 
                 	{
                 		tx_list = Stock_Transactions[Item == item_id && Store == store_id && Reference_Type == ref_type && Reference_Number == ref_number && Transaction_Type == "Stock In"];
                 		latest_id = null;
                 		latest_time = null;
                 		for each  tx in tx_list
                 		{
                 			if(latest_time == null || (tx.Created_Time != null && tx.Created_Time > latest_time))
                 			{
                 				latest_time = tx.Created_Time;
                 				latest_id = tx.ID;
                 			}
                 		}
                 		if(latest_id != null)
                 		{
                 			tx2 = Stock_Transactions[ID == latest_id];
                 			if(tx2.ID != null)
                 			{
                 				tx2.Display_Name_Store=display_store;
                 				tx2.Unit_Cost_Base=unit_cost_base;
                 				tx2.Line_Amount=(base_qty * unit_cost_base).round(2);
                 				tx2.Avg_Cost_After=new_avg;
                 			}
                 		}
                 	}	catch (e)
                 	{
                 		info "Unable to update optional stock transaction costing fields: " + e.toString();
                 	}
                 	// =====================================================
                 	// 12. RESPONSE
                 	// =====================================================
                 	result.put("ok",true);
                 	result.put("message","Stock In posted successfully.");
                 	return result;
                 }

map stock.rebuild_item_balances(int item_id)
{
                 	result = Map();
                 	result.put("ok",false);
                 	result.put("message","");
                 	// =====================================================
                 	// 1. VALIDATE ITEM
                 	// =====================================================
                 	if(item_id == null)
                 	{
                 		result.put("message","Item ID is required.");
                 		return result;
                 	}
                 	item_rec = Items_Register[ID == item_id];
                 	if(item_rec.ID == null)
                 	{
                 		result.put("message","Item was not found.");
                 		return result;
                 	}
                 	// Services do not require stock balance rebuilding.
                 	// Preserve existing values.
                 	if(item_rec.Is_Service == true)
                 	{
                 		result.put("ok",true);
                 		result.put("skipped",true);
                 		result.put("item_id",item_id);
                 		result.put("message","Stock rebuilding skipped because this item is a service.");
                 		return result;
                 	}
                 	// =====================================================
                 	// 2. INITIAL VALUES
                 	// =====================================================
                 	running_new_qty = 0.0;
                 	running_used_qty = 0.0;
                 	running_avg = ifnull(item_rec.Default_Cost,ifnull(item_rec.Average_Cost,0.0));
                 	new_stock_take_id = 0;
                 	used_stock_take_id = 0;
                 	new_checkpoint_id = 0;
                 	used_checkpoint_id = 0;
                 	new_checkpoint_found = false;
                 	used_checkpoint_found = false;
                 	processed_new_count = 0;
                 	processed_used_count = 0;
                 	skipped_checkpoint_count = 0;
                 	negative_balance_found = false;
                 	invalid_transaction_found = false;
                 	negative_transaction_ids = List();
                 	invalid_transaction_ids = List();
                 	// =====================================================
                 	// 3. LATEST CONFIRMED NEW STOCK-TAKING CHECKPOINT
                 	// =====================================================
                 	for each  new_checkpoint in Stock_Transactions[Item == item_id && Stock_Condition == "New" && Source_Form == "Stock Taking Details" || Item == item_id && Stock_Condition == "New" && Source_Form == "Stock_Taking_Details"] sort by ID desc range from 1 to 1
                 	{
                 		if(new_checkpoint.Source_Record_ID != null)
                 		{
                 			new_stock_take = Stock_Taking_Details[ID == new_checkpoint.Source_Record_ID && Item == item_id && Stock_Condition == "New"];
                 			if(new_stock_take.ID != null)
                 			{
                 				new_stock_take_id = new_stock_take.ID;
                 				new_checkpoint_id = new_checkpoint.ID;
                 				new_checkpoint_found = true;
                 				running_new_qty = ifnull(new_stock_take.Stock_In_Base_Unit_Of_Measure,0.0);
                 				if(new_stock_take.Cost != null && new_stock_take.Cost >= 0)
                 				{
                 					running_avg = new_stock_take.Cost;
                 				}
                 				else if(new_checkpoint.Avg_Cost_After != null && new_checkpoint.Avg_Cost_After >= 0)
                 				{
                 					running_avg = new_checkpoint.Avg_Cost_After;
                 				}
                 			}
                 		}
                 	}
                 	// =====================================================
                 	// 4. LATEST CONFIRMED USED STOCK-TAKING CHECKPOINT
                 	// =====================================================
                 	for each  used_checkpoint in Stock_Transactions[Item == item_id && Stock_Condition == "Used" && Source_Form == "Stock Taking Details" || Item == item_id && Stock_Condition == "Used" && Source_Form == "Stock_Taking_Details"] sort by ID desc range from 1 to 1
                 	{
                 		if(used_checkpoint.Source_Record_ID != null)
                 		{
                 			used_stock_take = Stock_Taking_Details[ID == used_checkpoint.Source_Record_ID && Item == item_id && Stock_Condition == "Used"];
                 			if(used_stock_take.ID != null)
                 			{
                 				used_stock_take_id = used_stock_take.ID;
                 				used_checkpoint_id = used_checkpoint.ID;
                 				used_checkpoint_found = true;
                 				running_used_qty = ifnull(used_stock_take.Stock_In_Base_Unit_Of_Measure,0.0);
                 			}
                 		}
                 	}
                 	// =====================================================
                 	// 5. COUNT TRANSACTIONS COVERED BY CHECKPOINTS
                 	// =====================================================
                 	if(new_checkpoint_found == true)
                 	{
                 		skipped_new_count = Stock_Transactions[Item == item_id && Stock_Condition == "New" && ID <= new_checkpoint_id || Item == item_id && Stock_Condition == null && ID <= new_checkpoint_id || Item == item_id && Stock_Condition == "" && ID <= new_checkpoint_id].count();
                 		skipped_checkpoint_count = skipped_checkpoint_count + skipped_new_count;
                 	}
                 	if(used_checkpoint_found == true)
                 	{
                 		skipped_used_count = Stock_Transactions[Item == item_id && Stock_Condition == "Used" && ID <= used_checkpoint_id].count();
                 		skipped_checkpoint_count = skipped_checkpoint_count + skipped_used_count;
                 	}
                 	// =====================================================
                 	// 6. PROCESS NEW TRANSACTIONS AFTER CHECKPOINT
                 	// =====================================================
                 	new_txns = Stock_Transactions[Item == item_id && Stock_Condition == "New" && ID > new_checkpoint_id || Item == item_id && Stock_Condition == null && ID > new_checkpoint_id || Item == item_id && Stock_Condition == "" && ID > new_checkpoint_id] sort by ID asc;
                 	for each  txn in new_txns
                 	{
                 		transaction_type = ifnull(txn.Transaction_Type,"").trim();
                 		transaction_qty = ifnull(txn.Quantity,0.0);
                 		if(transaction_qty < 0)
                 		{
                 			invalid_transaction_found = true;
                 			invalid_transaction_ids.add(txn.ID);
                 			continue;
                 		}
                 		if(transaction_qty == 0)
                 		{
                 			continue;
                 		}
                 		is_increase = false;
                 		is_decrease = false;
                 		if(transaction_type == "Stock In" || transaction_type == "Opening Stock" || transaction_type == "Adjustment Increase")
                 		{
                 			is_increase = true;
                 		}
                 		else if(transaction_type == "Stock Out" || transaction_type == "Adjustment Decrease")
                 		{
                 			is_decrease = true;
                 		}
                 		else
                 		{
                 			invalid_transaction_found = true;
                 			invalid_transaction_ids.add(txn.ID);
                 			continue;
                 		}
                 		// =============================================
                 		// NEW-STOCK AVERAGE COST
                 		// =============================================
                 		if(is_increase == true)
                 		{
                 			in_cost = ifnull(txn.Unit_Cost_Base,0.0);
                 			if(in_cost >= 0)
                 			{
                 				if(running_new_qty <= 0)
                 				{
                 					running_avg = in_cost;
                 				}
                 				else
                 				{
                 					running_avg = (running_new_qty * running_avg + transaction_qty * in_cost) / (running_new_qty + transaction_qty);
                 				}
                 			}
                 			running_new_qty = running_new_qty + transaction_qty;
                 		}
                 		else if(is_decrease == true)
                 		{
                 			running_new_qty = running_new_qty - transaction_qty;
                 		}
                 		if(running_new_qty < -0.000001)
                 		{
                 			negative_balance_found = true;
                 			negative_transaction_ids.add(txn.ID);
                 		}
                 		else if(running_new_qty >= -0.000001 && running_new_qty <= 0.000001)
                 		{
                 			running_new_qty = 0.0;
                 		}
                 		processed_new_count = processed_new_count + 1;
                 	}
                 	// =====================================================
                 	// 7. PROCESS USED TRANSACTIONS AFTER CHECKPOINT
                 	// =====================================================
                 	used_txns = Stock_Transactions[Item == item_id && Stock_Condition == "Used" && ID > used_checkpoint_id] sort by ID asc;
                 	for each  txn in used_txns
                 	{
                 		transaction_type = ifnull(txn.Transaction_Type,"").trim();
                 		transaction_qty = ifnull(txn.Quantity,0.0);
                 		if(transaction_qty < 0)
                 		{
                 			invalid_transaction_found = true;
                 			invalid_transaction_ids.add(txn.ID);
                 			continue;
                 		}
                 		if(transaction_qty == 0)
                 		{
                 			continue;
                 		}
                 		is_increase = false;
                 		is_decrease = false;
                 		if(transaction_type == "Stock In" || transaction_type == "Opening Stock" || transaction_type == "Adjustment Increase")
                 		{
                 			is_increase = true;
                 		}
                 		else if(transaction_type == "Stock Out" || transaction_type == "Adjustment Decrease")
                 		{
                 			is_decrease = true;
                 		}
                 		else
                 		{
                 			invalid_transaction_found = true;
                 			invalid_transaction_ids.add(txn.ID);
                 			continue;
                 		}
                 		if(is_increase == true)
                 		{
                 			running_used_qty = running_used_qty + transaction_qty;
                 		}
                 		else if(is_decrease == true)
                 		{
                 			running_used_qty = running_used_qty - transaction_qty;
                 		}
                 		if(running_used_qty < -0.000001)
                 		{
                 			negative_balance_found = true;
                 			negative_transaction_ids.add(txn.ID);
                 		}
                 		else if(running_used_qty >= -0.000001 && running_used_qty <= 0.000001)
                 		{
                 			running_used_qty = 0.0;
                 		}
                 		processed_used_count = processed_used_count + 1;
                 	}
                 	// =====================================================
                 	// 8. BLOCK UPDATE WHEN TRANSACTIONS ARE INVALID
                 	// =====================================================
                 	if(invalid_transaction_found == true)
                 	{
                 		result.put("message","Item was not rebuilt because invalid transactions were found.");
                 		result.put("invalid_transaction_ids",invalid_transaction_ids);
                 		result.put("new_checkpoint_id",new_checkpoint_id);
                 		result.put("used_checkpoint_id",used_checkpoint_id);
                 		return result;
                 	}
                 	if(negative_balance_found == true)
                 	{
                 		result.put("message","Item was not rebuilt because transactions after the checkpoint create negative stock.");
                 		result.put("negative_transaction_ids",negative_transaction_ids);
                 		result.put("calculated_new_qty",running_new_qty.round(2));
                 		result.put("calculated_used_qty",running_used_qty.round(2));
                 		return result;
                 	}
                 	// =====================================================
                 	// 9. FINAL VALUES
                 	// =====================================================
                 	running_qty = running_new_qty + running_used_qty;
                 	if(running_qty < -0.000001)
                 	{
                 		result.put("message","Item was not rebuilt because the total balance is negative.");
                 		return result;
                 	}
                 	if(running_qty >= -0.000001 && running_qty <= 0.000001)
                 	{
                 		running_qty = 0.0;
                 	}
                 	if(running_avg < 0)
                 	{
                 		running_avg = 0.0;
                 	}
                 	stock_value = running_qty * running_avg;
                 	// =====================================================
                 	// 10. UPDATE ITEM
                 	// =====================================================
                 	item_rec.Stock_On_Hand=running_qty.round(2);
                 	item_rec.Stock_On_Hand_New=running_new_qty.round(2);
                 	item_rec.Stock_On_Hand_Used=running_used_qty.round(2);
                 	item_rec.Average_Cost=running_avg.round(4);
                 	item_rec.Stock_Value=stock_value.round(2);
                 	// =====================================================
                 	// 11. RESULT
                 	// =====================================================
                 	processed_count = processed_new_count + processed_used_count;
                 	result.put("ok",true);
                 	result.put("message","Item balance rebuilt successfully from the latest confirmed stock-taking checkpoints.");
                 	result.put("item_id",item_id);
                 	result.put("qty",running_qty.round(2));
                 	result.put("new_qty",running_new_qty.round(2));
                 	result.put("used_qty",running_used_qty.round(2));
                 	result.put("average_cost",running_avg.round(4));
                 	result.put("stock_value",stock_value.round(2));
                 	result.put("processed_count",processed_count);
                 	result.put("processed_new_count",processed_new_count);
                 	result.put("processed_used_count",processed_used_count);
                 	result.put("skipped_checkpoint_count",skipped_checkpoint_count);
                 	result.put("new_checkpoint_found",new_checkpoint_found);
                 	result.put("used_checkpoint_found",used_checkpoint_found);
                 	result.put("new_stock_take_id",new_stock_take_id);
                 	result.put("used_stock_take_id",used_stock_take_id);
                 	result.put("new_checkpoint_id",new_checkpoint_id);
                 	result.put("used_checkpoint_id",used_checkpoint_id);
                 	return result;
                 }

void stock.rebuild_ledger_from_transactions()
{
                 	delete from Store_Item_Stock[ID != 0];
                 	trans_list = Stock_Transactions[ID != 0];
                 	for each  t in trans_list
                 	{
                 		if(t.Item == null || t.Store == null)
                 		{
                 			continue;
                 		}
                 		qty = ifnull(t.Quantity,0.0);
                 		if(qty <= 0)
                 		{
                 			continue;
                 		}
                 		delta = 0.0;
                 		if(t.Transaction_Type == "Stock In")
                 		{
                 			delta = qty;
                 		}
                 		else if(t.Transaction_Type == "Stock Out")
                 		{
                 			delta = -1 * qty;
                 		}
                 		else
                 		{
                 			continue;
                 		}
                 		condition = ifnull(t.Stock_Condition,"New");
                 		thisapp.stock.apply_ledger_delta(t.Item,t.Store,delta,condition);
                 	}
                 }

void stock.rebuild_store_item_stock_costs(int item_id, int store_id, string stock_condition)
{
                 	if(item_id == null || store_id == null)
                 	{
                 		return;
                 	}
                 	cond = ifnull(stock_condition,"New").trim();
                 	if(cond == "")
                 	{
                 		cond = "New";
                 	}
                 	led = Store_Item_Stock[Item == item_id && Store == store_id && Stock_Condition == cond];
                 	if(led.ID == null)
                 	{
                 		return;
                 	}
                 	trans_list = Stock_Transactions[Item == item_id && Store == store_id && Stock_Condition == cond] sort by Transaction_Date asc;
                 	run_qty = 0.0;
                 	run_avg = 0.0;
                 	last_in_cost = 0.0;
                 	for each  tx in trans_list
                 	{
                 		tx_qty = ifnull(tx.Quantity,0.0);
                 		if(tx_qty <= 0)
                 		{
                 			continue;
                 		}
                 		tx_type = ifnull(tx.Transaction_Type,"").trim();
                 		tx_cost = ifnull(tx.Unit_Cost_Base,0.0);
                 		if(tx_type == "Stock In")
                 		{
                 			if(tx_cost > 0)
                 			{
                 				if(run_qty <= 0)
                 				{
                 					run_avg = tx_cost;
                 				}
                 				else
                 				{
                 					run_avg = (run_qty * run_avg + tx_qty * tx_cost) / (run_qty + tx_qty);
                 				}
                 				last_in_cost = tx_cost;
                 			}
                 			run_qty = run_qty + tx_qty;
                 		}
                 		else if(tx_type == "Stock Out")
                 		{
                 			run_qty = run_qty - tx_qty;
                 			if(run_qty < 0)
                 			{
                 				run_qty = 0.0;
                 			}
                 		}
                 	}
                 	led.Default_Cost=last_in_cost;
                 	if(run_avg > 0)
                 	{
                 		led.Average_Cost=run_avg;
                 	}
                 	else
                 	{
                 		led.Average_Cost=ifnull(led.Default_Cost,0.0);
                 	}
                 	current_qty = ifnull(led.Qty_On_Hand,0.0);
                 	value_cost = ifnull(led.Average_Cost,0.0);
                 	if(value_cost <= 0)
                 	{
                 		value_cost = ifnull(led.Default_Cost,0.0);
                 	}
                 	if(current_qty > 0 && value_cost > 0)
                 	{
                 		led.Stock_Value=current_qty * value_cost;
                 	}
                 	else
                 	{
                 		led.Stock_Value=0.0;
                 	}
                 	led.Last_Updated=zoho.currenttime;
                 }

map stock.receive_stock_from_CleanSand(int item_id, int store_id, string display_name_store, float qty, int uom_id, string stock_condition, float unit_cost_uom, string ref_no, int source_record_id)
{
                 	result = Map();
                 	result.put("ok",false);
                 	result.put("message","");
                 	result.put("base_qty",0.0);
                 	result.put("unit_cost_base",0.0);
                 	result.put("line_total",0.0);
                 	// ==============================================
                 	// 1. VALIDATE REQUIRED VALUES
                 	// ==============================================
                 	if(item_id == null || store_id == null || qty == null || qty <= 0 || uom_id == null || source_record_id == null)
                 	{
                 		result.put("message","Missing item, store, quantity, UOM, or source record.");
                 		return result;
                 	}
                 	// ==============================================
                 	// 2. NORMALIZE STOCK CONDITION
                 	// ==============================================
                 	cond = ifnull(stock_condition,"New").trim();
                 	if(cond == "")
                 	{
                 		cond = "New";
                 	}
                 	// ==============================================
                 	// 3. NORMALIZE STORE DISPLAY NAME
                 	// ==============================================
                 	display_store = ifnull(display_name_store,"").trim();
                 	// Fallback to existing Store Item Stock
                 	if(display_store == "")
                 	{
                 		existing_ledger = Store_Item_Stock[Item == item_id && Store == store_id && Stock_Condition == cond];
                 		if(existing_ledger.ID != null)
                 		{
                 			display_store = ifnull(existing_ledger.Display_Name_Store,"").trim();
                 		}
                 	}
                 	// ==============================================
                 	// 4. RESOLVE REFERENCE
                 	// ==============================================
                 	ref_text = ifnull(ref_no,"").trim();
                 	if(ref_text == "")
                 	{
                 		ref_text = source_record_id.toString();
                 	}
                 	// ==============================================
                 	// 5. CONFIRM UOM CONVERSION EXISTS
                 	// ==============================================
                 	check = thisapp.uom.ensure_uom_conversion(item_id,uom_id);
                 	if(check.get("ok") != true)
                 	{
