                 	if(base_unit_cost > 0)
                 	{
                 		item_rec = Items_Register[ID == item_id];
                 		if(item_rec.ID != null)
                 		{
                 			item_rec.Default_Cost=base_unit_cost;
                 		}
                 	}
                 	// ==============================================
                 	// 11. REBUILD ITEM TOTALS
                 	// ==============================================
                 	thisapp.stock.rebuild_item_balances(item_id);
                 	// ==============================================
                 	// 12. ENSURE STORE ITEM STOCK DISPLAY NAMES
                 	// ==============================================
                 	item_rec2 = Items_Register[ID == item_id];
                 	display_item = "";
                 	if(item_rec2.ID != null)
                 	{
                 		item_name = ifnull(item_rec2.Item_Name,"").trim();
                 		item_sku = ifnull(item_rec2.SKU,"").trim();
                 		if(item_sku != "")
                 		{
                 			if(item_name != "")
                 			{
                 				display_item = item_name + " - " + item_sku;
                 			}
                 			else
                 			{
                 				display_item = item_sku;
                 			}
                 		}
                 		else
                 		{
                 			display_item = item_name;
                 		}
                 	}
                 	store_stock = Store_Item_Stock[Item == item_id && Store == store_id && Stock_Condition == cond];
                 	if(store_stock.ID != null)
                 	{
                 		store_stock.Display_Name_Item=display_item;
                 		store_stock.Display_Name_Store=display_store;
                 		store_stock.Last_Updated=zoho.currenttime;
                 	}
                 	// ==============================================
                 	// 13. SUCCESS RESPONSE
                 	// ==============================================
                 	result.put("ok",true);
                 	result.put("message","Stock received into Store Management from Masaka Site Management.");
                 	result.put("base_qty",base_qty);
                 	result.put("unit_cost_base",base_unit_cost);
                 	result.put("line_total",line_total);
                 	return result;
                 }

void stock.reconcile_stock_out_on_edit(int source_record_id, string source_form, int item_id, int store_id, float new_base_qty, string stock_condition, float line_total_value, string ref_form, string ref_no)
{
                 	// =====================================================
                 	// 1) VALIDATE REQUIRED VALUES
                 	// =====================================================
                 	if(source_record_id == null)
                 	{
                 		info "Stock reconciliation stopped: Source Record ID is empty.";
                 		return;
                 	}
                 	src_form = ifnull(source_form,"").trim();
                 	if(src_form == "")
                 	{
                 		info "Stock reconciliation stopped: Source Form is empty.";
                 		return;
                 	}
                 	if(item_id == null)
                 	{
                 		info "Stock reconciliation stopped: Item ID is empty.";
                 		return;
                 	}
                 	if(store_id == null)
                 	{
                 		info "Stock reconciliation stopped: Store ID is empty.";
                 		return;
                 	}
                 	// =====================================================
                 	// 2) STOCK CONDITION
                 	// Allows New, Used, In Service and other conditions.
                 	// =====================================================
                 	cond = ifnull(stock_condition,"New").trim();
                 	if(cond == "")
                 	{
                 		cond = "New";
                 	}
                 	// =====================================================
                 	// 3) QUANTITY AND REFERENCES
                 	// =====================================================
                 	new_qty = ifnull(new_base_qty,0.0);
                 	if(new_qty < 0)
                 	{
                 		info "Stock reconciliation stopped: New quantity cannot be negative.";
                 		return;
                 	}
                 	line_total = ifnull(line_total_value,0.0);
                 	ref_form_text = ifnull(ref_form,"").trim();
                 	ref_no_text = ifnull(ref_no,"").trim();
                 	if(ref_no_text == "")
                 	{
                 		ref_no_text = source_record_id.toString();
                 	}
                 	// =====================================================
                 	// 4) GET EXISTING STOCK-OUT TRANSACTIONS
                 	// =====================================================
                 	old_txns = Stock_Transactions[Source_Record_ID == source_record_id && Source_Form == src_form && Transaction_Type == "Stock Out"];
                 	old_count = 0;
                 	old_total_qty = 0.0;
                 	old_item_id = null;
                 	old_store_id = null;
                 	old_cond = "";
                 	for each  old_txn in old_txns
                 	{
                 		old_count = old_count + 1;
                 		old_qty = ifnull(old_txn.Quantity,0.0);
                 		if(old_qty < 0)
                 		{
                 			old_qty = old_qty * -1;
                 		}
                 		old_total_qty = old_total_qty + old_qty;
                 		if(old_count == 1)
                 		{
                 			old_item_id = old_txn.Item;
                 			old_store_id = old_txn.Store;
                 			if(old_store_id == null)
                 			{
                 				old_store_id = store_id;
                 			}
                 			old_cond = ifnull(old_txn.Stock_Condition,"New").trim();
                 			if(old_cond == "")
                 			{
                 				old_cond = "New";
                 			}
                 		}
                 	}
                 	// =====================================================
                 	// 5) CHECK WHETHER ANYTHING CHANGED
                 	// =====================================================
                 	needs_repost = false;
                 	if(old_count == 0)
                 	{
                 		if(new_qty > 0)
                 		{
                 			needs_repost = true;
                 		}
                 	}
                 	else
                 	{
                 		qty_diff = old_total_qty - new_qty;
                 		if(qty_diff < 0)
                 		{
                 			qty_diff = qty_diff * -1;
                 		}
                 		if(old_count != 1 || qty_diff > 0.000001 || old_item_id != item_id || old_store_id != store_id || old_cond != cond)
                 		{
                 			needs_repost = true;
                 		}
                 	}
                 	if(needs_repost == false)
                 	{
                 		info "Stock unchanged.";
                 		info "Old Stock Out found = " + old_count;
                 		info "Old base quantity = " + old_total_qty;
                 		info "New base quantity = " + new_qty;
                 		return;
                 	}
                 	// =====================================================
                 	// 6) CHECK AVAILABLE STOCK AFTER REVERSAL
                 	// =====================================================
                 	if(new_qty > 0)
                 	{
                 		current_stock_map = thisapp.stock.get_stock_summary(item_id,store_id,cond);
                 		if(current_stock_map == null)
                 		{
                 			info "Stock reconciliation stopped: Stock summary returned no response.";
                 			return;
                 		}
                 		current_store_stock = ifnull(current_stock_map.get("store_stock"),0.0);
                 		reversible_qty_same_target = 0.0;
                 		for each  old_txn_check in old_txns
                 		{
                 			old_check_cond = ifnull(old_txn_check.Stock_Condition,"New").trim();
                 			if(old_check_cond == "")
                 			{
                 				old_check_cond = "New";
                 			}
                 			old_check_store = old_txn_check.Store;
                 			if(old_check_store == null)
                 			{
                 				old_check_store = store_id;
                 			}
                 			old_check_qty = ifnull(old_txn_check.Quantity,0.0);
                 			if(old_check_qty < 0)
                 			{
                 				old_check_qty = old_check_qty * -1;
                 			}
                 			if(old_txn_check.Item == item_id && old_check_store == store_id && old_check_cond == cond)
                 			{
                 				reversible_qty_same_target = reversible_qty_same_target + old_check_qty;
                 			}
                 		}
                 		available_after_reverse = current_store_stock + reversible_qty_same_target;
                 		if(new_qty > available_after_reverse)
                 		{
                 			info "Stock reconciliation blocked: Insufficient stock.";
                 			info "Available after reversing old issue = " + available_after_reverse;
                 			info "Required = " + new_qty;
                 			return;
                 		}
                 	}
                 	// =====================================================
                 	// 7) REVERSE OLD LEDGER AND ITEM MOVEMENTS
                 	// =====================================================
                 	affected_items = List();
                 	for each  old_txn_reverse in old_txns
                 	{
                 		reverse_item_id = old_txn_reverse.Item;
                 		reverse_store_id = old_txn_reverse.Store;
                 		reverse_cond = ifnull(old_txn_reverse.Stock_Condition,"New").trim();
                 		if(reverse_cond == "")
                 		{
                 			reverse_cond = "New";
                 		}
                 		reverse_qty = ifnull(old_txn_reverse.Quantity,0.0);
                 		if(reverse_qty < 0)
                 		{
                 			reverse_qty = reverse_qty * -1;
                 		}
                 		if(reverse_item_id != null && reverse_store_id != null && reverse_qty > 0)
                 		{
                 			// Reverse the old Store Item Stock movement.
                 			thisapp.stock.apply_ledger_delta(reverse_item_id,reverse_store_id,reverse_qty,reverse_cond);
                 			// Restore the old global item balance.
                 			reverse_item_rec = Items_Register[ID == reverse_item_id];
                 			if(reverse_item_rec.ID != null)
                 			{
                 				reverse_item_rec.Stock_On_Hand=ifnull(reverse_item_rec.Stock_On_Hand,0.0) + reverse_qty;
                 				if(reverse_cond == "New")
                 				{
                 					reverse_item_rec.Stock_On_Hand_New=ifnull(reverse_item_rec.Stock_On_Hand_New,0.0) + reverse_qty;
                 				}
                 				else if(reverse_cond == "Used")
                 				{
                 					reverse_item_rec.Stock_On_Hand_Used=ifnull(reverse_item_rec.Stock_On_Hand_Used,0.0) + reverse_qty;
                 				}
                 				reverse_average_cost = ifnull(reverse_item_rec.Average_Cost,0.0);
                 				reverse_item_rec.Stock_Value=round(ifnull(reverse_item_rec.Stock_On_Hand,0.0) * reverse_average_cost,2);
                 			}
                 		}
                 		if(reverse_item_id != null && affected_items.contains(reverse_item_id) == false)
                 		{
                 			affected_items.add(reverse_item_id);
                 		}
                 	}
                 	// =====================================================
                 	// 8) DELETE OLD TRANSACTIONS
                 	// =====================================================
                 	for each  old_txn_delete in old_txns
                 	{
                 		delete from Stock_Transactions[ID == old_txn_delete.ID];
                 	}
                 	// =====================================================
                 	// 9) POST NEW STOCK-OUT TRANSACTION
                 	// =====================================================
                 	if(new_qty > 0)
                 	{
                 		unit_cost_base = 0.0;
                 		if(line_total > 0)
                 		{
                 			unit_cost_base = line_total / new_qty;
                 		}
                 		display_store = "";
                 		store_stock_rec = Store_Item_Stock[Item == item_id && Store == store_id && Stock_Condition == cond];
                 		if(store_stock_rec.ID != null)
                 		{
                 			display_store = ifnull(store_stock_rec.Display_Name_Store,"").trim();
                 		}
                 		thisapp.stock.log_stock_transaction(item_id,new_qty,"Stock Out",ref_form_text,ref_no_text,store_id,display_store,cond,unit_cost_base,src_form,source_record_id);
                 		if(affected_items.contains(item_id) == false)
                 		{
                 			affected_items.add(item_id);
                 		}
                 	}
                 	// =====================================================
                 	// 10) VERIFY NEW TRANSACTION
                 	// =====================================================
                 	if(new_qty > 0)
                 	{
                 		verify_txns = Stock_Transactions[Source_Record_ID == source_record_id && Source_Form == src_form && Transaction_Type == "Stock Out"];
                 		verify_count = 0;
                 		verify_qty = 0.0;
                 		verify_item_id = null;
                 		verify_store_id = null;
                 		verify_cond = "";
                 		for each  verify_txn in verify_txns
                 		{
                 			verify_count = verify_count + 1;
                 			verify_qty = verify_qty + ifnull(verify_txn.Quantity,0.0);
                 			if(verify_count == 1)
                 			{
                 				verify_item_id = verify_txn.Item;
                 				verify_store_id = verify_txn.Store;
                 				verify_cond = ifnull(verify_txn.Stock_Condition,"New").trim();
                 				if(verify_cond == "")
                 				{
                 					verify_cond = "New";
                 				}
                 			}
                 		}
                 		verify_difference = verify_qty - new_qty;
                 		if(verify_difference < 0)
                 		{
                 			verify_difference = verify_difference * -1;
                 		}
                 		if(verify_count != 1 || verify_difference > 0.000001 || verify_item_id != item_id || verify_store_id != store_id || verify_cond != cond)
                 		{
                 			info "Stock reconciliation failed: New Stock Out could not be verified.";
                 			info "Expected quantity = " + new_qty;
                 			info "Posted quantity = " + verify_qty;
                 			info "Posted transaction count = " + verify_count;
                 			return;
                 		}
                 	}
                 	info "Stock transaction reconciled successfully.";
                 	info "Old Stock Out found = " + old_count;
                 	info "Old base quantity = " + old_total_qty;
                 	info "New base quantity = " + new_qty;
                 	info "Stock condition = " + cond;
                 }

void stock.refresh_stock_taking_available_stock()
{
                 	pending = Stock_Taking_Details[Status == "Pending"];
                 	for each  r in pending
                 	{
                 		if(r.Item == null || r.Stock_Taking_Voucher == null)
                 		{
                 			continue;
                 		}
                 		stv = Stock_Taking_Voucher[ID == r.Stock_Taking_Voucher];
                 		if(stv.ID == null || stv.Store == null)
                 		{
                 			continue;
                 		}
                 		cond = ifnull(r.Stock_Condition,"New").trim();
                 		if(cond == "")
                 		{
                 			cond = "New";
                 		}
                 		// Refresh balances for this item
                 		thisapp.stock.rebuild_item_balances(r.Item);
                 		// Get latest store stock
                 		sis = Store_Item_Stock[Item == r.Item && Store == stv.Store && Stock_Condition == cond];
                 		qty = 0.0;
                 		if(sis.ID != null)
                 		{
                 			qty = ifnull(sis.Qty_On_Hand,0.0);
                 		}
                 		r.Store_Available_Stock=qty;
                 		r.Stock_Difference=round(ifnull(r.Counted_Stock,0.0) - qty,2);
                 	}
                 }

