map stock_transfer.create_transfer_from_item_issuing(map payload)
{
                 	response = Map();
                 	response.put("ok",false);
                 	// =====================================================
                 	// 1) SOURCE DETAILS
                 	// =====================================================
                 	source_record_id = ifnull(payload.get("Source_Record_ID"),0).toLong();
                 	source_form = ifnull(payload.get("Source_Form"),"").toString().trim();
                 	source_application = ifnull(payload.get("Source_Application"),"").toString().trim();
                 	if(source_record_id <= 0)
                 	{
                 		response.put("message","Source Record ID is required.");
                 		return response;
                 	}
                 	if(source_form == "")
                 	{
                 		response.put("message","Source Form is required.");
                 		return response;
                 	}
                 	if(source_application == "")
                 	{
                 		response.put("message","Source Application is required.");
                 		return response;
                 	}
                 	// =====================================================
                 	// 2) CHECK EXISTING TRANSFER
                 	// =====================================================
                 	existing_transfer = Stock_Transfer_Form[Source_Record_ID == source_record_id && Source_Form == source_form && Application == source_application];
                 	// =====================================================
                 	// 3) PAYLOAD VALUES
                 	// =====================================================
                 	transfer_number = ifnull(payload.get("Transfer_Number"),"").toString().trim();
                 	transfer_date = payload.get("Transfer_Date");
                 	issuing_store = payload.get("Issuing_Store");
                 	item_id = payload.get("Item");
                 	display_item = ifnull(payload.get("Display_Name_Item"),"").toString();
                 	qty = ifnull(payload.get("Quantity"),0.0).toDecimal();
                 	uom_id = payload.get("Unit_Of_Measure");
                 	display_uom = ifnull(payload.get("Display_Name_Unit_Of_Measure"),"").toString();
                 	base_qty = ifnull(payload.get("Quantity_in_Base_Unit_Of_Measure"),0.0).toDecimal();
                 	issued_by = ifnull(payload.get("Issued_By"),"").toString();
                 	stock_condition = ifnull(payload.get("Stock_Condition"),"New").toString().trim();
                 	unit_cost = ifnull(payload.get("Unit_Cost"),0.0).toDecimal();
                 	if(stock_condition == "")
                 	{
                 		stock_condition = "New";
                 	}
                 	// =====================================================
                 	// 4) VALIDATIONS
                 	// =====================================================
                 	if(issuing_store == null)
                 	{
                 		response.put("message","Issuing Store is required.");
                 		return response;
                 	}
                 	if(item_id == null)
                 	{
                 		response.put("message","Item is required.");
                 		return response;
                 	}
                 	if(uom_id == null)
                 	{
                 		response.put("message","Unit of Measure is required.");
                 		return response;
                 	}
                 	if(qty <= 0)
                 	{
                 		response.put("message","Quantity must be greater than zero.");
                 		return response;
                 	}
                 	if(base_qty <= 0)
                 	{
                 		response.put("message","Quantity in Base Unit of Measure must be greater than zero.");
                 		return response;
                 	}
                 	// =====================================================
                 	// 5) UPDATE EXISTING TRANSFER
                 	// =====================================================
                 	if(existing_transfer.ID != null)
                 	{
                 		existing_transfer.Transfer_Number=transfer_number;
                 		existing_transfer.Transfer_Date=transfer_date;
                 		existing_transfer.Issuing_Store=issuing_store;
                 		existing_transfer.Item=item_id;
                 		existing_transfer.Display_Name_Item=display_item;
                 		existing_transfer.Quantity=qty;
                 		existing_transfer.Unit_Of_Measure=uom_id;
                 		existing_transfer.Display_Name_Unit_of_Measure=display_uom;
                 		existing_transfer.Quantity_in_Base_Unit_Of_Measure=base_qty;
                 		existing_transfer.Issued_By=issued_by;
                 		existing_transfer.Stock_Condition=stock_condition;
                 		existing_transfer.Unit_Cost=unit_cost;
                 		existing_transfer.Application=source_application;
                 		existing_transfer.Source_Form=source_form;
                 		existing_transfer.Source_Record_ID=source_record_id;
                 		// Only reset this when it has not already been received
                 		if(existing_transfer.Receiving_Status == null || existing_transfer.Receiving_Status == "" || existing_transfer.Receiving_Status == "Draft")
                 		{
                 			existing_transfer.Receiving_Status="Not Received";
                 		}
                 		response.put("ok",true);
                 		response.put("message","Stock Transfer updated.");
                 		response.put("transfer_id",existing_transfer.ID);
                 		response.put("created",false);
                 		return response;
                 	}
                 	// =====================================================
                 	// 6) CREATE NEW TRANSFER
                 	// =====================================================
                 	new_transfer_id = insert into Stock_Transfer_Form
                 	[
                 		Transfer_Number=transfer_number
                 		Transfer_Date=transfer_date
                 		Issuing_Store=issuing_store
                 		Item=item_id
                 		Display_Name_Item=display_item
                 		Quantity=qty
                 		Unit_Of_Measure=uom_id
                 		Display_Name_Unit_of_Measure=display_uom
                 		Quantity_in_Base_Unit_Of_Measure=base_qty
                 		Issued_By=issued_by
                 		Stock_Condition=stock_condition
                 		Unit_Cost=unit_cost
                 		Receiving_Status="Not Received"
                 		Application=source_application
                 		Source_Record_ID=source_record_id
                 		Source_Form=source_form
                 		Added_User=zoho.loginuser
                 	];
                 	if(new_transfer_id == null)
                 	{
                 		response.put("message","Stock Transfer record could not be created.");
                 		return response;
                 	}
                 	// =====================================================
                 	// 7) RESPONSE
                 	// =====================================================
                 	response.put("ok",true);
                 	response.put("message","Stock Transfer created as Not Received.");
                 	response.put("transfer_id",new_transfer_id);
                 	response.put("created",true);
                 	return response;
                 }

map stock_transfer.mark_transfer_received(int transfer_id, decimal quantity_received, decimal base_quantity_received, int received_uom, string receiving_store, string received_by, string receiving_number, int receiving_record_id)
{
                 	resp = Map();
                 	resp.put("ok",false);
                 	if(transfer_id == null)
                 	{
                 		resp.put("message","Transfer ID is required.");
                 		return resp;
                 	}
                 	transfer_rec = Stock_Transfer_Form[ID == transfer_id];
                 	if(transfer_rec.ID == null)
                 	{
                 		resp.put("message","Stock Transfer record was not found.");
                 		return resp;
                 	}
                 	issued_qty = ifnull(transfer_rec.Quantity,0.0);
                 	new_received = ifnull(quantity_received,0.0);
                 	new_base_received = ifnull(base_quantity_received,0.0);
                 	if(new_received <= 0)
                 	{
                 		resp.put("message","Quantity Received must be greater than zero.");
                 		return resp;
                 	}
                 	if(issued_qty > 0 && new_received > issued_qty)
                 	{
                 		resp.put("message","Quantity Received cannot exceed transferred quantity.");
                 		return resp;
                 	}
                 	transfer_rec.Receiving_Number=ifnull(receiving_number,"");
                 	transfer_rec.Receive_Date=zoho.currentdate;
                 	transfer_rec.Receiving_Store=ifnull(receiving_store,"");
                 	transfer_rec.Quantity_Received=new_received;
                 	transfer_rec.Quantity_Received_in_Base_Unit_Of_Measure=new_base_received;
                 	if(received_uom != null)
                 	{
                 		transfer_rec.Unit_Of_Measure_Received=received_uom;
                 	}
                 	transfer_rec.Received_By=ifnull(received_by,"");
                 	transfer_rec.Receive_Application="Freedom City Management";
                 	transfer_rec.Receive_Source_Form="Stock Receiving Details";
                 	transfer_rec.Receive_Source_Record_ID=receiving_record_id;
                 	if(issued_qty > 0 && new_received < issued_qty)
                 	{
                 		transfer_rec.Receiving_Status="Partially Received";
                 	}
                 	else
                 	{
                 		transfer_rec.Receiving_Status="Fully Received";
                 	}
                 	resp.put("ok",true);
                 	resp.put("message","Stock Transfer receiving section updated.");
                 	resp.put("transfer_id",transfer_rec.ID);
                 	resp.put("receiving_status",transfer_rec.Receiving_Status);
                 	return resp;
                 }

map stock_transfer.reverse_transfer_receiving(map payload)
{
                 	response = Map();
                 	response.put("ok",false);
                 	source_record_id = payload.get("Receive_Source_Record_ID");
                 	source_form = ifnull(payload.get("Receive_Source_Form"),"");
                 	receive_application = ifnull(payload.get("Receive_Application"),"");
                 	if(source_record_id == null)
                 	{
                 		response.put("message","Receive Source Record ID is required.");
                 		return response;
                 	}
                 	source_record_id = source_record_id.toLong();
                 	transfer_rec = Stock_Transfer_Form[Receive_Source_Record_ID == source_record_id && Receive_Source_Form == source_form];
                 	if(transfer_rec.ID == null)
                 	{
                 		response.put("message","No Stock Transfer was found for the deleted receiving record.");
                 		return response;
                 	}
                 	transfer_rec.Quantity_Received=0.0;
                 	transfer_rec.Quantity_Received_in_Base_Unit_Of_Measure=0.0;
                 	transfer_rec.Receiving_Number="";
                 	transfer_rec.Receive_Date=null;
                 	transfer_rec.Receiving_Store="";
                 	transfer_rec.Unit_Of_Measure_Received=null;
                 	transfer_rec.Received_By="";
                 	transfer_rec.Receiving_Status="Not Received";
                 	transfer_rec.Receive_Application="";
                 	transfer_rec.Receive_Source_Form="";
                 	transfer_rec.Receive_Source_Record_ID=null;
                 	response.put("ok",true);
                 	response.put("message","Stock Transfer receiving details reversed successfully.");
                 	response.put("transfer_id",transfer_rec.ID);
                 	return response;
                 }

map stock_transfer.update_transfer_receiving_details(map payload)
{
                 	response = Map();
                 	response.put("ok",false);
                 	if(payload == null)
                 	{
                 		response.put("message","Receiving payload is required.");
                 		return response;
                 	}
                 	transfer_id = 0;
                 	if(payload.get("Transfer_ID") != null)
                 	{
                 		transfer_id = payload.get("Transfer_ID").toLong();
                 	}
                 	if(transfer_id <= 0)
                 	{
                 		response.put("message","Stock Transfer ID is required.");
                 		return response;
                 	}
                 	transfer_rec = Stock_Transfer_Form[ID == transfer_id];
                 	if(transfer_rec.ID == null)
                 	{
                 		response.put("message","Stock Transfer record was not found.");
                 		return response;
                 	}
                 	receiving_number = ifnull(payload.get("Receiving_Number"),"").toString().trim();
                 	receive_date = payload.get("Receive_Date");
                 	receiving_store = payload.get("Receiving_Store");
                 	received_uom = payload.get("Unit_Of_Measure_Received");
                 	quantity_received = 0.0;
                 	if(payload.get("Quantity_Received") != null)
                 	{
                 		quantity_received = payload.get("Quantity_Received").toDecimal();
                 	}
                 	base_quantity_received = 0.0;
                 	if(payload.get("Quantity_Received_in_Base_Unit_Of_Measure") != null)
                 	{
                 		base_quantity_received = payload.get("Quantity_Received_in_Base_Unit_Of_Measure").toDecimal();
                 	}
                 	received_by = ifnull(payload.get("Received_By"),"").toString().trim();
                 	receive_application = ifnull(payload.get("Receive_Application"),"").toString().trim();
                 	receive_source_form = ifnull(payload.get("Receive_Source_Form"),"").toString().trim();
                 	receive_source_record_id = 0;
                 	if(payload.get("Receive_Source_Record_ID") != null)
                 	{
                 		receive_source_record_id = payload.get("Receive_Source_Record_ID").toLong();
                 	}
                 	issued_quantity = ifnull(transfer_rec.Quantity,0.0);
                 	issued_base_quantity = ifnull(transfer_rec.Quantity_in_Base_Unit_Of_Measure,0.0);
                 	transfer_uom = transfer_rec.Unit_Of_Measure;
                 	existing_source_record_id = 0;
                 	if(transfer_rec.Receive_Source_Record_ID != null)
                 	{
                 		existing_source_record_id = transfer_rec.Receive_Source_Record_ID;
                 	}
                 	if(receiving_number == "")
                 	{
                 		response.put("message","Receiving Number is required.");
                 		return response;
                 	}
                 	if(receiving_store == null)
                 	{
                 		response.put("message","Receiving Store is required.");
                 		return response;
                 	}
                 	if(quantity_received <= 0)
                 	{
                 		response.put("message","Quantity Received must be greater than zero.");
                 		return response;
                 	}
                 	if(received_uom == null)
                 	{
                 		response.put("message","Unit Of Measure Received is required.");
                 		return response;
                 	}
                 	if(receive_source_record_id <= 0)
                 	{
                 		response.put("message","Receiving Source Record ID is required.");
                 		return response;
                 	}
                 	if(receive_application == "")
                 	{
                 		response.put("message","Receiving Application is required.");
                 		return response;
                 	}
                 	if(receive_source_form == "")
                 	{
                 		response.put("message","Receiving Source Form is required.");
                 		return response;
                 	}
                 	if(issued_quantity <= 0)
                 	{
                 		response.put("message","The Stock Transfer has no valid transferred quantity.");
                 		return response;
                 	}
                 	if(quantity_received > issued_quantity)
                 	{
                 		response.put("message","Quantity Received cannot exceed the transferred quantity of " + issued_quantity + ".");
                 		return response;
                 	}
                 	if(quantity_received != issued_quantity)
                 	{
                 		response.put("message","Quantity Received must exactly match the transferred quantity of " + issued_quantity + ".");
                 		return response;
                 	}
                 	if(transfer_uom != null && received_uom != transfer_uom)
                 	{
                 		response.put("message","Unit Of Measure Received must match the transferred Unit Of Measure.");
                 		return response;
                 	}
                 	if(base_quantity_received <= 0)
                 	{
                 		response.put("message","Quantity Received in Base Unit Of Measure must be greater than zero.");
                 		return response;
                 	}
                 	if(issued_base_quantity > 0 && base_quantity_received > issued_base_quantity)
                 	{
                 		response.put("message","Received base quantity cannot exceed the transferred base quantity of " + issued_base_quantity + ".");
                 		return response;
                 	}
                 	if(issued_base_quantity > 0 && base_quantity_received != issued_base_quantity)
                 	{
                 		response.put("message","Received base quantity must exactly match the transferred base quantity of " + issued_base_quantity + ".");
                 		return response;
                 	}
                 	if(transfer_rec.Issuing_Store != null && receiving_store == transfer_rec.Issuing_Store)
                 	{
                 		response.put("message","Issuing Store and Receiving Store cannot be the same.");
                 		return response;
                 	}
                 	if(existing_source_record_id > 0 && existing_source_record_id != receive_source_record_id)
                 	{
                 		response.put("message","This Stock Transfer Item is already linked to another Stock Receiving record.");
                 		return response;
                 	}
                 	transfer_rec.Receiving_Number=receiving_number;
                 	if(receive_date != null)
                 	{
                 		transfer_rec.Receive_Date=receive_date;
                 	}
                 	else
                 	{
                 		transfer_rec.Receive_Date=zoho.currentdate;
                 	}
                 	transfer_rec.Receiving_Store=receiving_store;
                 	transfer_rec.Quantity_Received=quantity_received;
                 	transfer_rec.Unit_Of_Measure_Received=received_uom;
                 	transfer_rec.Quantity_Received_in_Base_Unit_Of_Measure=base_quantity_received;
                 	transfer_rec.Received_By=received_by;
                 	transfer_rec.Receive_Application=receive_application;
                 	transfer_rec.Receive_Source_Form=receive_source_form;
                 	transfer_rec.Receive_Source_Record_ID=receive_source_record_id;
                 	transfer_rec.Receiving_Status="Fully Received";
                 	response.put("ok",true);
                 	response.put("message","Stock Transfer receiving details synchronized successfully.");
                 	response.put("transfer_id",transfer_rec.ID);
                 	response.put("quantity_transferred",issued_quantity);
                 	response.put("quantity_received",quantity_received);
                 	response.put("base_quantity_received",base_quantity_received);
                 	response.put("receiving_status",transfer_rec.Receiving_Status);
                 	return response;
                 }

void uom.ensure_base_uom_conversion(int item_id)
{
                 	if(item_id == null)
                 	{
                 		return;
                 	}
                 	item_rec = Items_Register[ID == item_id];
                 	if(item_rec.ID == null || item_rec.Base_Unit_Of_Measure == null)
                 	{
                 		return;
                 	}
                 	base_uom = item_rec.Base_Unit_Of_Measure;
                 	// Get UoM name
                 	uom_name = "";
                 	uom_rec = Unit_Of_Measure[ID == base_uom];
                 	if(uom_rec.ID != null)
                 	{
                 		uom_name = uom_rec.Unit_Of_Measure_Name;
                 	}
                 	// Remove old base conversions
                 	old_base_rows = Unit_Of_Measure_Conversion[Item == item_id && Is_Base_Conversion == true && Base_Unit_Of_Measure != base_uom || Alternate_Unit_Of_Measure != base_uom];
                 	for each  r in old_base_rows
                 	{
                 		delete from Unit_Of_Measure_Conversion[ID == r.ID];
                 	}
                 	// Ensure correct base -> base conversion exists
                 	existing = Unit_Of_Measure_Conversion[Item == item_id && Base_Unit_Of_Measure == base_uom && Alternate_Unit_Of_Measure == base_uom];
                 	if(existing.count() == 0)
                 	{
                 		insert into Unit_Of_Measure_Conversion
                 		[
                 			Item=item_id
                 			Display_Name_Item=item_rec.Item_Name
                 			Base_Unit_Of_Measure=base_uom
                 			Display_Name_Base_Unit_Of_Measure=uom_name
                 			Alternate_Unit_Of_Measure=base_uom
                 			Display_Name_Alternate_Unit_Of_Measure=uom_name
                 			Conversion_Factor=1
                 			Is_Base_Conversion=true
                 			Added_User=zoho.loginuser
                 		]
                 	}
                 	else
                 	{
                 		for each  row in existing
                 		{
                 			row.Display_Name_Item=item_rec.Item_Name;
                 			row.Display_Name_Base_Unit_Of_Measure=uom_name;
                 			row.Display_Name_Alternate_Unit_Of_Measure=uom_name;
                 			row.Conversion_Factor=1;
                 			row.Is_Base_Conversion=true;
                 		}
                 	}
                 }

map uom.ensure_uom_conversion(int item_id, int selected_uom)
{
                 	result = Map();
                 	result.put("ok",false);
                 	result.put("message","");
                 	result.put("conversion_factor",1.0);
                 	if(item_id == null || selected_uom == null)
                 	{
                 		result.put("message","Item or Unit Of Measure is missing.");
                 		return result;
                 	}
                 	item_rec = Items_Register[ID == item_id];
                 	if(item_rec.ID == null)
                 	{
                 		result.put("message","Item record not found.");
                 		return result;
                 	}
                 	base_uom = item_rec.Base_Unit_Of_Measure;
                 	if(base_uom == null)
                 	{
                 		result.put("message","This Item has no Base Unit Of Measure defined.");
                 		return result;
                 	}
                 	// If same as base, it's fine
                 	if(selected_uom == base_uom)
                 	{
                 		result.put("ok",true);
                 		result.put("conversion_factor",1.0);
                 		return result;
                 	}
                 	// Check conversion
                 	conv = Unit_Of_Measure_Conversion[Item == item_rec.ID && Base_Unit_Of_Measure == base_uom && Alternate_Unit_Of_Measure == selected_uom];
                 	if(conv.count() == 0)
                 	{
                 		base_name = "";
                 		sel_name = "";
                 		base_uom_rec = Unit_Of_Measure[ID == base_uom];
                 		if(base_uom_rec.ID != null)
                 		{
                 			base_name = base_uom_rec.Unit_Of_Measure_Name;
                 		}
                 		sel_rec = Unit_Of_Measure[ID == selected_uom];
                 		if(sel_rec.ID != null)
                 		{
                 			sel_name = sel_rec.Unit_Of_Measure_Name;
                 		}
                 		msg = "No Unit of Measure conversion is defined for Item '" + item_rec.Item_Name + "' between '" + base_name + "' and '" + sel_name + "'. Please first create this conversion in Unit Of Measure Conversion.";
                 		result.put("message",msg);
                 		return result;
                 	}
                 	// Valid conversion
                 	result.put("ok",true);
                 	result.put("conversion_factor",conv.Conversion_Factor);
                 	return result;
                 }
